const e=[{id:1,code:"GOV-101",icon:"DoorOpen",accent:"#2563eb",title:"پلانی چۆڵکردنی تەنگانە",subtitle:"Emergency Evacuation Plans",summary:"دانانی پلانی چۆڵکردن بۆ فەرمانگە و بینا حکومییەکان",blocks:[{body:"پلانی چۆڵکردنی تەنگانە یەکێکە لە گرنگترین بەڵگەنامەکانی هەر فەرمانگەیەکی حکومی. ئەم پلانە ژیانی فەرمانبەران و سەردانکەران دەپارێزێت لە کاتی ڕووداوەکانی وەک ئاگرکەوتنەوە، بوومەلەرزە یان مەترسییە کیمیاییەکان."},{heading:"١. هەنگاوەکانی دانانی پلان",body:"پلانێکی سەرکەوتوو پێویستی بەم هەنگاوانە هەیە:",points:["نەخشە: نەخشەیەکی تەواوی بیناکە لەگەڵ ڕێگاکانی دەرچوون و شوێنی ئاگرکوژێنەرەوەکان ئامادە بکە.","ڕێگاکانی دەرچوون: هەر نهۆمێک لانیکەم دوو ڕێگای دەرچوونی دوور لە یەکتری هەبێت (NFPA 101)، و دەرگاکانی دەرچوون دەبێت لە ناوەوە بەبێ کلیل بکرێنەوە.","خاڵی کۆبوونەوە: شوێنێکی سەلامەت لە دەرەوەی بیناکە، بە دووریی پێشنیارکراوی لانیکەم ٥٠ مەتر.","بەرپرسیارێتی: بۆ هەر نهۆمێک بەرپرسێکی چۆڵکردن دیاری بکە.","سیستەمی ئاگادارکردنەوە: زەنگ یان سیرینی ئاگر کە لە هەموو نهۆمەکاندا ببیسترێت.","ڕاهێنان: هەر ٣ مانگ جارێک ڕاهێنانی پراکتیکیی چۆڵکردن."]},{heading:"٢. ڕێساکانی چۆڵکردنی سەلامەت",body:"کاتێک زەنگی ئاگادارکردنەوە لێدرا:",points:["بە ئارامی و ڕێکوپێکی بڕۆ — ڕامەکە.","ئاسانسۆر بەکار مەهێنە — تەنها بە پلیکانەکاندا دەربچۆ.","ئەگەر دووکەڵ هەبوو، خۆت نزم بکەرەوە و لە ژێر دووکەڵەکەدا بە گاگۆڵکێ بڕۆ.","پێش کردنەوە، بە پشتی دەست دەرگاکە بپشکنە — ئەگەر گەرم بوو مەیکەرەوە و ڕێگایەکی تر بدۆزەرەوە.","یارمەتیی ئەو کەسانە بدە کە پێویستیان بە یارمەتییە و دەرگاکان لە دوای خۆتەوە دابخە.","ڕاستەوخۆ بڕۆ بۆ خاڵی کۆبوونەوە و لەوێ بمێنەرەوە."]},{heading:"٣. ڕۆڵی بەرپرسان",body:"هەر نهۆمێک پێویستی بە بەرپرسێکی ئاگر هەیە:",points:["بەرپرسی ئاگر (Fire Warden): بەرپرسی سەرەکیی نهۆمەکە.","پشکنینی هەموو ژوورەکان (تەوالێت و کۆگاکانیش) بۆ ئەوەی کەس نەمێنێتەوە.","ڕێنماییکردنی خەڵک بۆ ڕێگاکانی دەرچوون.","ژماردنی خەڵک لە خاڵی کۆبوونەوە و ئاگادارکردنەوەی تیمی ١١٥."]}],media:[{kind:"image",src:"media/images/gov_evacuation.png",title:"نەخشەی چۆڵکردن",description:"نموونەی نەخشەیەک"}],quiz:[{question:"پێشنیار دەکرێت خاڵی کۆبوونەوە چەند لە بیناکە دوور بێت؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٥ مەتر",correct:!1},{text:"٥٠ مەتر",correct:!0},{text:"١٠٠ مەتر",correct:!1}],explanation:"لانیکەم ٥٠ مەتر، بۆ ئەوەی لە کەوتنی شووشە و پارچەکان و لە دووکەڵ دوور بێت و ڕێگای ئۆتۆمبێلەکانی تەنگانە نەگرێت."}]},{id:2,code:"GOV-102",icon:"FileLock",accent:"#059669",title:"پاراستنی بەڵگەنامەکان",subtitle:"Document Protection",summary:"ڕێکارەکانی پاراستنی بەڵگەنامە گرنگەکان لە ئاگر و ئاو",blocks:[{body:"بەڵگەنامە حکومییەکان سامانێکی بەنرخن. لەناوچوونیان بە ئاگر یان ئاو دەتوانێت کاری فەرمانگە ڕابگرێت و مافەکانی خەڵک لەناو ببات. بۆیە پاراستن و کۆپیکردنیان پێویستە."},{heading:"١. پۆلێنکردنی بەڵگەنامەکان",body:"دیاریکردنی گرنگیی بەڵگەنامەکان:",points:["ئاستی A — زۆر گرنگ: گرێبەست، دارایی، یاسایی.","ئاستی B — گرنگ: ڕاپۆرت و نامە فەرمییەکان.","ئاستی C — ئاسایی: نامە نافەرمییەکان."]},{heading:"٢. پاراستنی فیزیکی",body:"ڕێکارەکانی پاراستنی فیزیکی:",points:["سەیفی بەرگەگری ئاگر: بۆ بەڵگەنامەکانی ئاستی A.","دۆڵابی کانزاییی قفڵدراو، بەرزتر لە زەوی.","کیس و سندووقی پلاستیکیی دژە ئاو.","کۆنترۆڵکردنی ژینگە: شوێنێکی فێنک و وشک بە پلەی گەرمی و ڕێژەی شێی جێگیر."]},{heading:"٣. ڕێسای ٣-٢-١ بۆ کۆپیی یەدەگ (Backup)",body:"ڕێسای ٣-٢-١:",points:["٣ کۆپی لە هەر داتایەکی گرنگ.","٢ جۆری جیاوازی هەڵگرتن (میدیا).","١ کۆپی لە شوێنێکی تر، لە دەرەوەی بیناکە."]}],media:[{kind:"image",src:"media/images/gov_backup.png",title:"کۆپیی یەدەگ (Backup)",description:"ڕێسای ٣-٢-١"}],quiz:[{question:"ڕێسای ٣-٢-١ مانای چییە؟",options:[{text:"٣ کۆمپیوتەر",correct:!1},{text:"٣ کۆپی، ٢ جۆری میدیا، ١ لە دەرەوە",correct:!0},{text:"٣ ڕۆژ",correct:!1},{text:"٣ فەرمانبەر",correct:!1}],explanation:"٣ کۆپی لەسەر ٢ جۆری میدیا، و ١ کۆپی لە شوێنێکی تر لە دەرەوەی بیناکە."}]},{id:3,code:"GOV-103",icon:"Zap",accent:"#ca8a04",title:"سەلامەتیی کارەبا",subtitle:"Electrical Safety",summary:"مەترسییەکانی کارەبا لە فەرمانگەکاندا و پشکنینی ئامێرەکان",blocks:[{body:"کارەبا یەکێکە لە هۆکارە سەرەکییەکانی ئاگرکەوتنەوە لە فەرمانگەکاندا. وایەرە کۆنەکان، زیادەبارکردنی پلاکەکان و ئامێرەکانی گەرمکردنەوە دەبێت بە ڕێکوپێکی بپشکنرێن."},{heading:"١. مەترسییەکانی کارەبا",body:"مەترسییە باوەکان لە فەرمانگەکاندا:",points:["زیادەبارکردن: زۆر ئامێر لەسەر یەک پلاک.","وایەری کۆن کە بەرگەکەی قڵیشاوە یان شکاوە.","ئاو لە نزیک ئامێر و پلاکەکانی کارەبا.","وایەری درێژکەرەوە (Extension): بەکارهێنانی زۆر و هەمیشەییان."]},{heading:"٢. ڕێساکانی سەلامەتی",body:"ڕێسا ڕۆژانەکان:",points:["وایەری درێژکەرەوە بە وایەرێکی درێژکەرەوەی ترەوە مەبەستەوە.","پێش دەستلێدانی پلاک، دەبێت دەستەکانت وشک بن.","ئامێری گەرمکەرەوە ڕاستەوخۆ بە پلاکی دیوارەوە ببەستە، نەک بە وایەری درێژکەرەوە."]},{heading:"٣. ئاگری کارەبایی",body:"ئەگەر ئاگر لە ئامێرێکی کارەبایی کەوتەوە:",points:["ئەگەر بە سەلامەتی دەتوانیت، کارەبا لە تابلۆکەوە ببڕە و پەیوەندی بە ١١٥ بکە.","ئەگەر ئاگرەکە بچووک بێت و تۆ ڕاهێنراو بیت، ئاگرکوژێنەرەوەی CO₂ یان تۆزی وشک (ABC) بەکاربهێنە و ڕێگای دەرچوون لە پشتتەوە بێت؛ ئەگەر نا، دەربچۆ.","ئاو و کەف نا، مەگەر لەسەر لەیبڵەکە پۆلی C یان نیشانەی تاقیکردنەوەی کارەبایی هەبێت — مەترسیی شۆکی کارەبا هەیە."]}],media:[{kind:"video",src:"media/videos/gov_electrical.mp4",title:"سەلامەتیی کارەبا",description:"ڕێنمایی"}],quiz:[{question:"کام ئاگرکوژێنەرەوە باشترە بۆ ئاگری کارەبایی؟",options:[{text:"ئاو",correct:!1},{text:"کەف",correct:!1},{text:"CO₂ یان تۆزی وشک",correct:!0},{text:"بەتانی",correct:!1}],explanation:"CO₂ و تۆزی وشک کارەبا ناگوازنەوە؛ ئاو و کەفی ئاسایی کارەبا دەگوازنەوە و دەتوانن شۆک دروست بکەن."}]},{id:4,code:"GOV-104",icon:"HeartPulse",accent:"#dc2626",title:"بەرنامەی فریاکەوتنی سەرەتایی",subtitle:"First Aid Program",summary:"پێکهێنانی تیمی فریاکەوتنی سەرەتایی و ئامادەکردنی کەرەستەکان",blocks:[{body:"هەر فەرمانگەیەک پێویستی بە بەرنامەیەکی فریاکەوتنی سەرەتایی هەیە. پێشنیار دەکرێت لە هەر نهۆمێک و لە هەر دەوامێکدا لانیکەم یەک کەسی ڕاهێنراو هەبێت، و لە فەرمانگە گەورەکاندا زیاتر."},{heading:"١. تیمی فریاکەوتنی سەرەتایی",body:"پێکهاتەی تیم:",points:["لانیکەم یەک کەسی ڕاهێنراو لە هەر نهۆمێک و لە هەر دەوامێکدا.","خولێکی پەسەندکراوی فریاکەوتنی سەرەتایی، فشاری سنگ (CPR) و AED.","نوێکردنەوەی ڕاهێنان و بڕوانامە هەر ٢ ساڵ جارێک."]},{heading:"٢. سندووقی فریاکەوتنی سەرەتایی",body:"کەرەستە پێویستەکان:",points:["باند (Bandage) و پەڕۆی پاکی برینپێچ (Gauze).","مادەی پاککردنەوەی برین (Antiseptic).","مقەست و پەنس.","دەستکێشی پزیشکیی یەکجاری.","ماسکی CPR بۆ هەناسەدان بە سەلامەتی."]},{heading:"٣. فشاری سنگ (CPR)",body:"هەنگاوەکانی CPR بۆ گەورەساڵان:",points:["١. ئەگەر کەسەکە وەڵام ناداتەوە و بە دروستی هەناسە نادات: پەیوەندی بە ١٢٢ بکە و داوای AED بکە؛ لەسەر پشت لەسەر زەوییەکی ڕەق دایبنێ.","٢. ٣٠ فشاری سنگ لە ناوەڕاستی سنگ: قووڵی ٥-٦ سم، خێرایی ١٠٠-١٢٠ فشار لە خولەکێکدا.","٣. ٢ هەناسە (هەریەکەیان نزیکەی ١ چرکە) ئەگەر ڕاهێنراو بیت؛ ئەگەر نا، تەنها فشاری سنگ بکە.","٤. بە ڕێژەی ٣٠:٢ بەردەوام بە تا AED یان ئەمبولانس دەگات؛ AED یەکسەر بەکاربهێنە."]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"فشاری سنگ (CPR)",description:"چۆنیەتیی ئەنجامدانی CPR"}],quiz:[{question:"لە CPR دا، پێش ٢ هەناسەکە چەند فشاری سنگ دەکرێت؟",options:[{text:"١٠",correct:!1},{text:"١٥",correct:!1},{text:"٣٠",correct:!0},{text:"٥٠",correct:!1}],explanation:"ڕێژەی دروست بۆ گەورەساڵان ٣٠:٢ یە (AHA 2025)."}]},{id:5,code:"GOV-105",icon:"Flame",accent:"#ea580c",title:"ئاگر و ئاگرکوژێنەرەوە لە فەرمانگەکاندا",subtitle:"Fire Prevention & Extinguisher Use",summary:"ڕێگریکردن لە ئاگرکەوتنەوە و بەکارهێنانی ئاگرکوژێنەرەوەکان لە بینا حکومییەکاندا",blocks:[{body:"ئاگرکەوتنەوە لە فەرمانگەکاندا مەترسییەکی جددییە. کاغەز، کۆمپیوتەر، وایەری کۆن و زیادەبارکردنی کارەبا هۆکارە سەرەکییەکانی ئاگرن. بەرنامەیەکی ڕێگری و ئامادەکاری ژیانی فەرمانبەران و سامانی گشتی دەپارێزێت."},{heading:"١. هۆکارەکانی ئاگر لە فەرمانگەکاندا",body:"هۆکارە سەرەکییەکان:",points:["زیادەبارکردنی کارەبا: زۆر ئامێر لەسەر یەک پلاک.","کاغەز و بەڵگەنامە: مادەی بە ئاسانی سووتاو.","جگەرە و شقارتە: هۆکارێکی سەرەکیی هەڵگیرسانی ئاگر.","سۆبە و گەرمکەرەوەی گوازراوە: مەترسیی زستان.","چێشتخانە بچووکەکان: لە کاتی ئامادەکردنی چا و قاوە.","پاتری و شەحنکەر: گەرمبوونی زیادە."]},{heading:"٢. جۆرەکانی ئاگرکوژێنەرەوە",body:"بۆ فەرمانگەکان ئەم جۆرانە پێویستن:",points:["ئاگرکوژێنەرەوەی تۆزی وشک (ABC): بۆ ئاگرەکانی پۆلی A، B و C — نەک بۆ کانزاکان (D) و نەک بۆ ڕۆنی چێشتخانە (K).","ئاگرکوژێنەرەوەی CO₂: بۆ ئاگری ئامێرە کارەباییەکان — زیان بە کۆمپیوتەرەکان ناگەیەنێت.","ئاگرکوژێنەرەوەی ئاو: تەنها بۆ پۆلی A (کاغەز، دار، جل) — نەک بۆ کارەبا و ڕۆن.","کۆدی بەریتانی BS 5306-8 پێشنیار دەکات کە لانیکەم ٢ ئاگرکوژێنەرەوە لە هەر نهۆمێکدا هەبێت (جگە لە نهۆمە زۆر بچووکەکان)؛ یاسای فەرمانگەکانی دهۆک لەلایەن بەڕێوەبەرایەتیی بەرگریی شارستانییەوە دادەنرێت و هێشتا پشتڕاست نەکراوەتەوە.","ئاگرکوژێنەرەوەکان لە نزیک دەرگاکان و لەسەر ڕێگاکانی دەرچوون دابنێ.","پشکنینی بینراوی مانگانە (سنجاقی سەلامەتی و مۆرەکە نەشکابن، لەیبڵەکە بخوێنرێتەوە، ئەگەر دەرزیی پەستان هەبوو لە ناوچە سەوزەکەدا بێت؛ ئاگرکوژێنەرەوەی CO₂ دەرزیی پەستانی نییە، بۆیە هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە) و پشکنین و چاکردنەوەی ساڵانە لەلایەن کەسێکی شارەزاوە (NFPA 10)."]},{heading:"٣. ڕێکاری PASS",body:`پێش بەکارهێنانی ئاگرکوژێنەرەوە (دەبێت هەموو وەڵامەکان «بەڵێ» بن):
• ئاگرەکە بچووکە و تازە دەستی پێکردووە، وەک ئاگرێک لە سەتڵی خاشاک یان تاوەیەکدا.
• ئاگرکوژێنەرەوەکە گونجاوە بۆ ئەم جۆرە ئاگرە.
• ڕێگای دەرچوون لە پشتتەوەیە و ئاگرەکە لە نێوان تۆ و دەرچوونەکەدا نییە.
• ئاگادارکردنەوە دراوە: ئەوانی تر ئاگادار کراونەتەوە و پەیوەندی بە ١١٥ەوە کراوە.
• تۆ بۆ بەکارهێنانی ئاگرکوژێنەرەوە ڕاهێنراویت.
• هیچ دووکەڵ یان گەرمایەک ڕێگای دەرچوونت ناگرێت.
• ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، بوەستە، دەربچۆ و دەرگاکە لە دوای خۆتەوە دابخە.

ڕێکاری PASS ڕێگای گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان. ئاگرکوژێنەرەوەکانی Class D، مادەی تەڕ (Wet Chemical)، مادەی پاک (Clean Agent) و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە. چۆنیەتیی بەکارهێنانی ئاگرکوژێنەرەوە:`,points:["P = Pull (ڕایبکێشە): سنجاقی سەلامەتی ڕابکێشە و دەریبهێنە.","A = Aim (ئاراستەی بکە): سەری لوولەکە (Nozzle) ئاراستەی بنی ئاگرەکە بکە.","S = Squeeze (بیگووشە): دەسکی ئاگرکوژێنەرەوەکە بە هێز بگووشە.","S = Sweep (بیجووڵێنە): لە بنی ئاگرەکەدا لە لایەکەوە بۆ لایەکی تر بیجووڵێنە.","دووری: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە یان لە ڕێنماییەکانی کۆمپانیای دروستکەردا هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","ڕێگای دەرچوون لە پشت خۆتەوە بهێڵەرەوە؛ ئەگەر ئاگرەکە یەکسەر نەکوژایەوە یان دەستی بە بڵاوبوونەوە کرد، دەربچۆ، دەرگاکە لە دوای خۆتەوە دابخە و دڵنیا ببەوە کە پەیوەندی بە ١١٥ەوە کراوە."]},{heading:"٤. سیستەمەکانی ئاگادارکردنەوە",body:"سیستەمە پێویستەکان لە فەرمانگەکاندا:",points:["سیرینی ئاگر: دەبێت لە هەموو نهۆمێکدا ببیسترێت.","دوگمەی ئاگادارکردنەوە (Pull Station): لە نزیک دەرچوونەکان.","دۆزینەوەی دووکەڵ (Smoke Detection): بەپێی ئەوەی کۆدی ئاگری بیناکە (Fire Code) داوای دەکات (پێداویستیی فەرمانگەکانی دهۆک هێشتا پشتڕاست نەکراوەتەوە).","ڕووناکیی تەنگانە: کاتێک کارەبا دەبڕێت خۆکارانە هەڵدەبێت.","ژمارە ١١٥ لەسەر دیواری هەموو ژوورێک بنووسە."]}],media:[{kind:"video",src:"media/videos/gov_fire_prevention.mp4",title:"ڕێگریکردن لە ئاگر",description:"ڕێنماییی تەواو بۆ فەرمانگەکان"},{kind:"image",src:"media/images/gov_pass_method.png",title:"ڕێکاری PASS",description:"هەنگاو بە هەنگاو"},{kind:"image",src:"media/images/gov_extinguisher_types.png",title:"جۆرەکانی ئاگرکوژێنەرەوە",description:"ABC، CO₂، ئاو"}],quiz:[{question:"کام ئاگرکوژێنەرەوە باشترە بۆ ئاگری کۆمپیوتەرەکان؟",options:[{text:"ئاگرکوژێنەرەوەی ئاو",correct:!1},{text:"ئاگرکوژێنەرەوەی CO₂",correct:!0},{text:"ئاگرکوژێنەرەوەی کەف",correct:!1},{text:"بەتانی",correct:!1}],explanation:"CO₂ زیان بە کۆمپیوتەرەکان ناگەیەنێت و کارەبا ناگوازێتەوە."},{question:"لە ڕێکاری PASS دا، A مانای چییە؟",options:[{text:"Alert (ئاگاداری)",correct:!1},{text:"Aim (ئاراستەی بکە)",correct:!0},{text:"Action (کار)",correct:!1},{text:"Away (دوور)",correct:!1}],explanation:"A = Aim: سەری لوولەکە ئاراستەی بنی ئاگرەکە بکە."},{question:"کۆدی بەریتانی BS 5306-8 لانیکەم چەند ئاگرکوژێنەرەوە لە هەر نهۆمێکدا پێشنیار دەکات؟",options:[{text:"١ ئاگرکوژێنەرەوە",correct:!1},{text:"٢ ئاگرکوژێنەرەوە",correct:!0},{text:"٣ ئاگرکوژێنەرەوە",correct:!1},{text:"٥ ئاگرکوژێنەرەوە",correct:!1}],explanation:"کۆدی بەریتانی BS 5306-8 پێشنیار دەکات کە لانیکەم ٢ ئاگرکوژێنەرەوە لە هەر نهۆمێکدا هەبێت (جگە لە نهۆمە زۆر بچووکەکان)، و دەبێت دووریی گەیشتن پێیان لە سنوور تێنەپەڕێت. یاسای فەرمانگەکانی دهۆک لەلایەن بەڕێوەبەرایەتیی بەرگریی شارستانییەوە دادەنرێت و هێشتا پشتڕاست نەکراوەتەوە."}]},{id:6,code:"GOV-106",icon:"Activity",accent:"#d97706",title:"بوومەلەرزە لە بینا حکومییەکاندا",subtitle:"Earthquake Safety in Gov Buildings",summary:"چۆنیەتیی پاراستنی خۆت و چۆڵکردنی سەلامەت لە کاتی بوومەلەرزەدا",blocks:[{body:"هەرێمی کوردستان دەکەوێتە سەر ناوچەیەکی چالاکی بوومەلەرزە. بینا حکومییەکان، بەتایبەتی کۆنەکان، مەترسیدارن. ئامادەباشی و زانینی ڕێکارەکان ژیان ڕزگار دەکات."},{heading:"١. لە کاتی بوومەلەرزەدا",body:"ئەگەر لە ناو فەرمانگەدا بوویت:",points:["خۆت بدە بە زەویدا (Drop): یەکسەر لەسەر چۆک و دەستەکانت دابنیشە.","خۆت بشارەوە (Cover): بڕۆ ژێر مێزێکی بەهێز، دوور لە پەنجەرە و دۆڵابە قورسەکان (نەک لە بەردەم دەرگا)، و سەر و ملت بپارێزە.","خۆت ڕابگرە (Hold On): قاچی مێزەکە بگرە تا لەرزینەکە ڕادەوەستێت.","بەرەو دەرەوە ڕامەکە — زۆرێک لە برینداربوونەکان لە کاتی ڕاکردن و بەهۆی کەوتنی پارچەکانەوە ڕوودەدەن.","ئاسانسۆر بەکار مەهێنە — لەوانەیە بوەستێت و تۆ تێیدا گیر بخۆیت.","ئەگەر لە شوێنێکی کراوەدا بوویت: دوور بە لە بیناکان، تێلەکانی کارەبا و ستوونەکان."]},{heading:"٢. دوای بوومەلەرزە",body:"هەنگاوەکانی دوای بوومەلەرزە:",points:["خۆت و هاوکارەکانت بۆ برینداربوون بپشکنە.","بە پلیکانەکاندا دەربچۆ (ئاسانسۆر نا!)","ئەگەر بۆنی گازت کرد یان گوێت لە دەنگی دزەکردنی گاز بوو: دەربچۆ و لە دەرەوە پەیوەندی بە ١١٥ بکە؛ تەنها کارمەندانی ڕاهێنراو و دەستنیشانکراو گاز لە سەمامەی سەرەکییەوە دادەخەن، ئەگەر گەیشتن پێی سەلامەت بوو، بەبێ چوونە ناو ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ دەستدان لە هیچ سویچێک.","بڕۆ بۆ خاڵی کۆبوونەوە و خەڵکەکە بژمێرە.","ئەگەر بریندار یان کەسی ژێر داڕماوەکان هەبوون، پەیوەندی بە ١١٥ و ١٢٢ بکە.","ئاگاداری لەرزینەکانی دواتر (Aftershocks) بە.","مەگەڕێرەوە ناو بیناکە تا شارەزایان سەلامەتییەکەی پشتڕاست نەکەنەوە."]},{heading:"٣. ئامادەکاریی پێشوەختە",body:"ئامادەکارییە پێویستەکان:",points:["پلانی بوومەلەرزە ئامادە بکە و لەسەر دیوار هەڵیواسە.","دۆڵاب، ڕەف و ئامێرە قورسەکان بە دیوارەوە قایم بکە.","جانتای تەنگانە لە هەر نهۆمێکدا ئامادە بکە.","پشکنینی بیناکە لەلایەن ئەندازیارێکی شارەزاوە هەموو ساڵێک.","ڕاهێنانی Drop, Cover, Hold On هەر ٣ مانگ جارێک.","دوو خاڵی کۆبوونەوە دیاری بکە (یەکێکیان نزیک و یەکێکیان دوور)."]},{heading:"٤. بەرپرسیارێتیی بەڕێوەبەران",body:"بەڕێوەبەران دەبێت:",points:["بۆ هەر نهۆمێک بەرپرسێکی بوومەلەرزە دیاری بکەن.","لیستی فەرمانبەران بۆ ژماردنی خەڵک ئامادە بهێڵنەوە.","پلانێکی تایبەت بۆ کەسانی خاوەن پێداویستیی تایبەت دابنێن.","سیستەمی ئاگادارکردنەوە بە ڕێکوپێکی بپشکنن.","ژمارەکانی تەنگانە (١١٥، ١٢٢، ١٠٤) لە هەموو ژوورێکدا بنووسن."]}],media:[{kind:"video",src:"media/videos/gov_earthquake.mp4",title:"بوومەلەرزە لە فەرمانگەدا",description:"ڕاهێنانی پراکتیکی"},{kind:"image",src:"media/images/gov_drop_cover_hold.png",title:"خۆت بدە بە زەویدا، خۆت بشارەوە، خۆت ڕابگرە (Drop, Cover, Hold On)",description:"هەنگاو بە هەنگاو"}],quiz:[{question:"لە کاتی بوومەلەرزەدا، یەکەم کار چییە؟",options:[{text:"بەرەو دەرەوە ڕابکە",correct:!1},{text:"بڕۆ ناو ئاسانسۆر",correct:!1},{text:"خۆت بدە بە زەویدا، خۆت بشارەوە، خۆت ڕابگرە (Drop, Cover, Hold On)",correct:!0},{text:"پەنجەرەکان بکەرەوە",correct:!1}],explanation:"لە ژێر مێزێکی بەهێزدا خۆت بدە بە زەویدا، خۆت بشارەوە و خۆت ڕابگرە تا لەرزینەکە ڕادەوەستێت."},{question:"دوای بوومەلەرزە، بۆ دەرچوون لە بیناکە چی بەکاردەهێنین؟",options:[{text:"ئاسانسۆر",correct:!1},{text:"پلیکانەکانی بیناکە",correct:!0},{text:"پەنجەرە",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"هەمیشە بە پلیکانەکاندا دەربچۆ — لەوانەیە ئاسانسۆر بوەستێت."},{question:"بەپێی ئەم بەرنامەیە، ڕاهێنانی بوومەلەرزە لە فەرمانگەدا هەر چەند جار جارێک پێویستە؟",options:[{text:"هەموو ساڵێک",correct:!1},{text:"هەر ٦ مانگ جارێک",correct:!1},{text:"هەر ٣ مانگ جارێک",correct:!0},{text:"تەنها یەک جار",correct:!1}],explanation:"ئەم بەرنامەیە پێشنیار دەکات هەر ٣ مانگ جارێک ڕاهێنانی پراکتیکی ئەنجام بدرێت."}]},{id:7,code:"GOV-107",icon:"Wind",accent:"#475569",title:"سەلامەتیی گاز و هەواگۆڕکێ",subtitle:"Gas Safety & Ventilation",summary:"مەترسییەکانی گاز لە فەرمانگەکاندا و گرنگیی هەواگۆڕکێی دروست",blocks:[{body:"لە زستاندا سۆبە و گەرمکەرەوەی گاز و نەوت لە فەرمانگەکاندا زۆر بەکاردەهێنرێن. دزەکردنی گاز دەتوانێت ببێتە هۆی تەقینەوە و ئاگر، و سووتانی ناتەواو گازی ژەهراویی مۆنۆکسیدی کاربۆن (CO) دروست دەکات کە بێڕەنگ و بێبۆنە و دەتوانێت بکوژێت. هەواگۆڕکێی دروست و ناسینی مەترسییەکان ژیان ڕزگار دەکات."},{heading:"١. مەترسیی گازی مۆنۆکسیدی کاربۆن (CO)",body:"CO بکوژێکی بێدەنگە:",points:["CO بێڕەنگ، بێبۆن و بێتامە — بە هەستەکان ناناسرێتەوە.","نیشانەکان: سەرئێشە، سەرگێژخواردن، دڵتێکهەڵاتن و ڕشانەوە، تێکچوونی هۆش؛ دواتر بێهۆشی و مردن.","سەرچاوە: سۆبەی گاز و نەوت لە ژووری بێ هەواگۆڕکێ.","زستان مەترسیدارترین وەرزە، چونکە دەرگا و پەنجەرەکان داخراون.","سنووری OSHA بۆ کرێکاران بریتییە لە ٥٠ ppm (تێکڕای ٨ کاتژمێر)، بەڵام لە ژووری کاردا دەبێت CO نزیکەی سفر بێت؛ هەر ڕێژەیەکی CO نیشانەی کەمیی هەواگۆڕکێیە."]},{heading:"٢. ڕێساکانی هەواگۆڕکێی دروست",body:"هەواگۆڕکێی پێویست لە فەرمانگەکاندا:",points:["کاتێک سۆبەی بێ بۆری کار دەکات، پەنجەرەیەک کەمێک کراوە بهێڵەرەوە بۆ ئەوەی هەوای تازە بێتە ژوورەوە.","ژوورێک کە سۆبەی بۆریی دووکەڵداری (Chimney) تێدایە: پانکەی دەرکێشی هەوا (Extractor Fan) لە هەمان کاتدا کار پێ مەکە، مەگەر تەکنیکارێکی شارەزا دڵنیای کردبێتەوە کە دووکەڵی سۆبەکە هێشتا بە سەلامەتی دەردەچێت؛ پانکەکە دەتوانێت دووکەڵ و گازی CO بکێشێتەوە ناو ژوورەکە، تەنانەت ئەگەر پانکەکە لە ژوورێکی تردا بێت.","بۆریی دووکەڵ (Chimney): دەبێت ساغ و کراوە بێت، نەک گیراو.","ڕاڕەو و ڕێگاکانی دەرچوون بە سۆبە مەگرە.","سۆبەی بێ بۆری پێش خەوتن و کاتێک ژوورەکە جێدەهێڵیت بکوژێنەرەوە، و جار جار هەوای ژوورەکە نوێ بکەرەوە.","چێشتخانە و تەوالێت دەبێت هەواگۆڕکێی تایبەتیان هەبێت."]},{heading:"٣. دزەکردنی گاز — چی بکەم؟",body:"ئەگەر بۆنی گازت کرد:",points:["ئەگەر توانیت، لە ڕێگای دەرچوونتدا پەنجەرە و دەرگاکان بکەرەوە.","هیچ شقارتەیەک دامەگیرسێنە و دەست لە سویچەکانی کارەبا مەدە (نە هەڵیانبکە و نە بیانکوژێنەرەوە)!","مۆبایل لە ناو بیناکەدا بەکار مەهێنە — پریشکێک دەتوانێت تەقینەوە دروست بکات.","دەربچۆ و هەموو کەسێک دەربهێنە.","لە دەرەوەی بیناکەوە پەیوەندی بە ١١٥ بکە.","تەنها کارمەندانی ڕاهێنراو و دەستنیشانکراو گاز لە سەمامەی سەرەکییەوە دادەخەن، ئەگەر گەیشتن پێی سەلامەت بوو و بەبێ چوونە ناو ئەو شوێنەی گازی تێدا کۆبووەتەوە؛ هەرگیز بۆ گەیشتن پێی مەگەڕێرەوە ژوورەوە."]},{heading:"٤. پشکنینی مانگانە",body:"پشکنین:",points:["بۆریی دووکەڵی سۆبەکە بپشکنە — دەبێت گیراو نەبێت.","جومگەکانی بۆریی گاز بە ئاو و سابوون بپشکنە (تاقیکردنەوەی کەف)؛ هەرگیز بە ئاگر مەیپشکنە.","ئامێری دۆزینەوەی CO (Carbon Monoxide Detector) دابنێ.","تەکنیسیەنێکی شارەزا هەموو ساڵێک سۆبەکان بپشکنێت.","تۆماری پشکنینەکان بپارێزە."]}],media:[{kind:"video",src:"media/videos/gov_gas_safety.mp4",title:"مەترسیی گاز",description:"چۆنیەتیی ناسینەوە و ڕێکارەکان"},{kind:"image",src:"media/images/gov_co_detector.png",title:"ئامێری دۆزینەوەی CO",description:"شوێنی دانان"}],quiz:[{question:"CO (مۆنۆکسیدی کاربۆن) چ تایبەتمەندییەکی هەیە؟",options:[{text:"بۆنێکی ناخۆشی هەیە",correct:!1},{text:"ڕەنگی سوورە",correct:!1},{text:"بێڕەنگ و بێبۆنە",correct:!0},{text:"هیچ تایبەتمەندییەکی نییە",correct:!1}],explanation:"CO بێڕەنگ، بێبۆن و بێتامە — بۆیە مەترسیدارە و ئامێری دۆزینەوە پێویستە."},{question:"ئەگەر بۆنی گازت کرد، یەکەم کار چییە؟",options:[{text:"گڵۆپی کارەبا هەڵبکە",correct:!1},{text:"دەربچۆ و لە ڕێگاتدا پەنجەرەکان بکەرەوە",correct:!0},{text:"مۆبایل بەکاربهێنە",correct:!1},{text:"سۆبەکە هەڵبکە",correct:!1}],explanation:"دەست لە ئاگر و سویچەکان مەدە، ئەگەر توانیت لە ڕێگای دەرچوونتدا پەنجەرەکان بکەرەوە، دەربچۆ و لە دەرەوە پەیوەندی بە ١١٥ بکە."},{question:"سۆبەی گازی بێ بۆری دەبێت کەی بکوژێنرێتەوە؟",options:[{text:"تەنها کاتێک گازەکە تەواو دەبێت",correct:!1},{text:"پێش خەوتن و کاتێک ژوورەکە جێدەهێڵیت",correct:!0},{text:"تەنها لە هاویندا",correct:!1},{text:"پێویست بە کوژاندنەوە ناکات",correct:!1}],explanation:"هەرگیز سۆبەی بێ بۆری لە کاتی خەوتندا یان کاتێک کەس لە ژوورەکەدا نییە داگیرساو مەهێڵەرەوە؛ جار جار هەوای ژوورەکە نوێ بکەرەوە."}]},{id:8,code:"GOV-108",icon:"Lock",accent:"#0891b2",title:"ئاسایشی سایبەری و داتاکان",subtitle:"Cybersecurity & Data Protection",summary:"پاراستنی سیستەمە کۆمپیوتەرییەکان و داتا حکومییەکان لە هێرشی ئەلیکترۆنی و ڤایرۆس",blocks:[{body:"لە سەردەمی دیجیتاڵیدا، هێرشە سایبەرییەکان مەترسییەکی گەورەن بۆ فەرمانگە حکومییەکان. داتا تایبەتییەکانی خەڵک، بەڵگەنامە فەرمییەکان و سیستەمە داراییەکان هەموویان دەبنە ئامانج. ئامادەباشی و ڕاهێنانی فەرمانبەران پێویستە."},{heading:"١. جۆرەکانی مەترسیی سایبەری",body:"مەترسییە سەرەکییەکان:",points:["فیشینگ (Phishing): ئیمەیڵ و نامەی ساختە کە دەیانەوێت زانیاری بدزن.","ڤایرۆس و بەرنامەی زیانبەخش (Malware).","ڕانسۆموێر (Ransomware): قفڵکردنی داتاکان و داواکردنی پارە.","ئەندازیاریی کۆمەڵایەتی (Social Engineering): فریودانی فەرمانبەران بۆ وەرگرتنی زانیاری.","تۆڕی WiFi ی نەپارێزراو: دزینی زانیاری لەسەر تۆڕەکە.","فلاشی USB ی نەناسراو: دەتوانن ڤایرۆس بگوازنەوە."]},{heading:"٢. ڕێساکانی وشەی نهێنی (Password)",body:"وشەی نهێنیی بەهێز:",points:["درێژی: لانیکەم ١٥ پیت و هێما (NIST SP 800-63B-4).","ڕستەیەکی درێژ لە چەند وشەیەک (Passphrase) بە ئاسانی لە بیرت دەمێنێت و بەهێزە.","وشەی نهێنی بە ماوەیەکی دیاریکراو مەگۆڕە؛ تەنها کاتێک گومان هەبێت کە ئاشکرا بووە بیگۆڕە.","ناو، ژمارەی تەلەفۆن یان ١٢٣٤٥٦ بەکار مەهێنە.","پشتڕاستکردنەوەی دوو قۆناغی (2FA) چالاک بکە.","بۆ هەر سیستەمێک وشەیەکی نهێنیی جیاواز بەکاربهێنە."]},{heading:"٣. ئیمەیڵی سەلامەت",body:"چۆنیەتیی پاراستنی خۆت لە ئیمەیڵدا:",points:["لینکی نەناسراو مەکەرەوە — ناونیشانی نێرەر بپشکنە.","فایلی هاوپێچکراو لە ناونیشانی نەناسراوەوە مەکەرەوە.","ئەگەر ئیمەیڵێکی گوماناوی هات، بەشی IT ئاگادار بکەرەوە.","وشەی نهێنی و ژمارەی هەژماری بانک بە ئیمەیڵ مەنێرە.","تەنها ئیمەیڵی فەرمی بۆ کارەکانی فەرمانگە بەکاربهێنە."]},{heading:"٤. پاراستنی فیزیکی",body:"پاراستنی ئامێرەکان:",points:["کاتێک لە مێزەکەت دوور دەکەویتەوە، کۆمپیوتەرەکەت قفڵ بکە (Win+L).","مەهێڵە کەسانی تر زانیارییەکان لەسەر شاشەکەت ببینن.","فلاشی USB ی نەناسراو مەخە ناو کۆمپیوتەرەوە.","کاغەزە نهێنییەکان بە ئامێری وردکردن (Shredder) لەناو ببە.","مۆبایلی کار بە PIN یان پەنجەمۆر بپارێزە."]}],media:[{kind:"video",src:"media/videos/gov_cybersecurity.mp4",title:"ئاسایشی سایبەری",description:"بنەماکانی پاراستن"},{kind:"image",src:"media/images/gov_phishing.png",title:"ناسینەوەی فیشینگ",description:"نموونەی ئیمەیڵی ساختە"}],quiz:[{question:"فیشینگ (Phishing) چییە؟",options:[{text:"بەرنامەیەکی باش",correct:!1},{text:"ئیمەیڵی ساختە بۆ دزینی زانیاری",correct:!0},{text:"جۆرێکی ئاگر",correct:!1},{text:"سیستەمی کۆپیی یەدەگ",correct:!1}],explanation:"فیشینگ ئیمەیڵی ساختەیە کە وەک ئیمەیڵی فەرمی دەردەکەون بۆ دزینی زانیاری."},{question:"وشەی نهێنیی بەهێز دەبێت لانیکەم چەند پیت و هێما بێت؟",options:[{text:"٤",correct:!1},{text:"٦",correct:!1},{text:"٨",correct:!1},{text:"١٥",correct:!0}],explanation:"NIST (SP 800-63B-4) بۆ وشەی نهێنیی بێ 2FA لانیکەم ١٥ هێما داوا دەکات؛ درێژی لە تێکەڵکردنی هێماکان گرنگترە."},{question:"ئەگەر فلاشێکی USB ی نەناسراوت لەسەر زەوی بینی، چی دەکەیت؟",options:[{text:"بیخە ناو کۆمپیوتەرەوە",correct:!1},{text:"بیدە بە بەرپرسی IT",correct:!0},{text:"بیبە بۆ ماڵەوە",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"فلاشی نەناسراو لەوانەیە ڤایرۆسی تێدا بێت — بیدە بە بەشی IT."}]},{id:9,code:"GOV-109",icon:"ShieldAlert",accent:"#7c3aed",title:"ئاسایشی کەسی و ڕێگریکردن لە توندوتیژی",subtitle:"Personal Safety & Workplace Security",summary:"پاراستنی فەرمانبەران لە مەترسییە ئەمنییەکان و توندوتیژیی شوێنی کار",blocks:[{body:"سەلامەتیی فەرمانبەران تەنها ئاگر و کارەبا نییە. توندوتیژی لە شوێنی کار، هەڕەشەکردن و ڕووداوە ئەمنییەکانیش پێویستیان بە ئامادەکاری هەیە. هەر فەرمانبەرێک دەبێت بزانێت چۆن لەم بارودۆخانەدا خۆی بپارێزێت."},{heading:"١. مەترسییە ئەمنییەکان لە فەرمانگەکاندا",body:"بارودۆخە ئەمنییەکان:",points:["سەردانکەری توڕە و ناڕازی.","هەڕەشەی جەستەیی.","پاکەت و شتی گوماناوی.","هێرشی چەکداری، دزی یان تاڵانکردن.","بارمتەگرتن.","هەڕەشەکردن بە تەلەفۆن یان لە ڕێگەی ئینتەرنێتەوە."]},{heading:"٢. ڕابکە، خۆت بشارەوە، ڕایبگەیەنە (Run, Hide, Tell)",body:"ئەگەر ڕووداوێکی ئەمنی ڕوویدا:",points:["Run (ڕابکە): ئەگەر ڕێگایەکی سەلامەت هەبوو، بە خێرایی لە بیناکە دەربچۆ.","هەمیشە نزیکترین ڕێگای دەرچوون بزانە.","Hide (خۆت بشارەوە): ئەگەر نەتتوانی ڕابکەیت، لە ژوورێکدا خۆت بشارەوە و دەرگاکە قفڵ بکە.","مۆبایلەکەت بێدەنگ بکە و لەرینەوەکەشی بکوژێنەرەوە.","Tell (ڕایبگەیەنە): کاتێک لە شوێنێکی سەلامەتدا بوویت، پەیوەندی بە ١٠٤ (پۆلیس) بکە.","هەموو زانیارییەکان بە وردی بڵێ: شوێن، ژمارەی کەسەکان و وەسفیان."]},{heading:"٣. مامەڵەکردن لەگەڵ سەردانکەری توڕە",body:"ڕێکارەکانی هێورکردنەوەی بارودۆخ:",points:["بە دەنگێکی هێمن و نزم قسە بکە.","گوێ بگرە و نیشانی بدە کە تێدەگەیت.","دوورییەکی سەلامەت (١٫٥-٢ مەتر) بپارێزە.","هەمیشە ڕێگای دەرچوونی خۆت کراوە بهێڵەرەوە.","هاوکارێک ئاگادار بکەرەوە بۆ ئەوەی بێت یارمەتیت بدات.","ئەگەر بارودۆخەکە خراپتر بوو، دوگمەی تەنگانە دابگرە یان پەیوەندی بە ١٠٤ بکە."]},{heading:"٤. ئامادەکاریی فەرمانگە",body:"ئامادەکارییە ئەمنییەکان:",points:["کامێرای چاودێری (CCTV) دابنێ.","سیستەمی کۆنترۆڵکردنی هاتنە ژوورەوە (Access Control).","دوگمەی تەنگانە (Panic Button) لە ژێر مێزەکانی پێشوازی.","ڕاهێنانی فەرمانبەران هەر ٦ مانگ جارێک.","پلانی ئەمنی نوێ بکەرەوە و تاقی بکەرەوە.","پەیوەندییەکی ڕاستەوخۆ لەگەڵ نزیکترین بنکەی پۆلیس دابمەزرێنە."]}],media:[{kind:"video",src:"media/videos/gov_security.mp4",title:"ئاسایشی کەسی",description:"ڕابکە، خۆت بشارەوە، ڕایبگەیەنە (Run, Hide, Tell)"},{kind:"image",src:"media/images/gov_deescalation.png",title:"ڕێکارەکانی هێورکردنەوە",description:"مامەڵەکردن لەگەڵ سەردانکەری توڕە"}],quiz:[{question:"لە ڕێکاری Run, Hide, Tell دا، یەکەم هەنگاو چییە؟",options:[{text:"خۆت بشارەوە",correct:!1},{text:"ڕابکە",correct:!0},{text:"بەرەنگاری بکە",correct:!1},{text:"پەیوەندی بە پۆلیسەوە بکە",correct:!1}],explanation:"یەکەم کار: Run (ڕابکە) ئەگەر ڕێگایەکی سەلامەت هەبوو."},{question:"لە کاتی مامەڵەکردن لەگەڵ سەردانکەرێکی توڕەدا، چی دەکەیت؟",options:[{text:"تۆش بە دەنگی بەرز قسە بکە",correct:!1},{text:"بە هێمنی قسە بکە و گوێ بگرە",correct:!0},{text:"گوێی پێ مەدە",correct:!1},{text:"دەرگاکەی لێ دابخە",correct:!1}],explanation:"بە هێمنی قسە بکە و گوێ بگرە — ئەمە بارودۆخەکە هێور دەکاتەوە."},{question:"ژمارەی پۆلیس لە هەرێمی کوردستان چەندە؟",options:[{text:"١١٥",correct:!1},{text:"١٢٢",correct:!1},{text:"١٠٤",correct:!0},{text:"٩١١",correct:!1}],explanation:"١٠٤ ژمارەی پۆلیسە لە هەرێمی کوردستان."}]},{id:10,code:"GOV-110",icon:"Armchair",accent:"#16a34a",title:"تەندروستی و سەلامەتیی شوێنی کار",subtitle:"Occupational Health & Ergonomics",summary:"پاراستنی تەندروستیی فەرمانبەران لە شوێنی کار و ڕێکخستنی دروستی مێز و کورسی",blocks:[{body:"فەرمانبەرانی حکومی زۆر جار ٨ کاتژمێر یان زیاتر لەبەردەم کۆمپیوتەر دادەنیشن. ئەمە دەبێتە هۆی ئازاری پشت، چاو و شان. ڕێکخستنی دروستی شوێنی کار (Ergonomics) و جووڵەی جەستەیی تەندروستیی کارمەندان دەپارێزێت."},{heading:"١. ڕێکخستنی مێز و کورسی (Ergonomics)",body:"شوێنی کاری دروست:",points:["کورسی: پاڵپشتی بۆ پشت هەبێت؛ بەرزییەکەی ڕێک بخە تا پێیەکانت بە تەواوی لەسەر زەوی بن.","شاشە: سەری شاشەکە لە ئاستی چاو یان کەمێک نزمتر بێت، بە دووریی ٥٠-٧٠ سم.","تەختەکلیل: ئانیشکەکان بە گۆشەیەکی نزیکەی ٩٠° بن.","ماوس: نزیک لە تەختەکلیل و لە هەمان ئاستدا.","بەرزیی مێز: دەبێت لەگەڵ باڵات بگونجێت.","ڕووناکی: ڕووناکی ڕاستەوخۆ نەکەوێتە سەر شاشەکە."]},{heading:"٢. پاراستنی چاو",body:"ماندووبوونی چاو بەهۆی شاشەوە (Computer Vision Syndrome):",points:["ڕێسای ٢٠-٢٠-٢٠: هەر ٢٠ خولەک جارێک، بۆ ماوەی ٢٠ چرکە سەیری شتێک بکە کە ٢٠ پێ (نزیکەی ٦ مەتر) دوور بێت.","زۆر چاو بتروکێنە — لەبەردەم شاشەدا چاوترووکاندن کەم دەبێتەوە و چاوەکان وشک دەبن.","لە ئێوارەدا ڕووناکیی شاشە کەم بکەرەوە.","دۆخی شەو (Night Mode) چالاک بکە.","چاویلکەی دژە ڕووناکیی شین (Blue Light) هیچ سوودێکی سەلمێنراویان نییە (AAO)؛ ئەگەر چاوەکانت وشک یان ماندوو بوون، سەردانی پزیشکی چاو بکە.","هەموو ساڵێک پشکنینی چاو بکە."]},{heading:"٣. ئازاری پشت و شان",body:"ڕێگری و چارەسەر:",points:["هەر ٤٥ خولەک جارێک هەستە و کەمێک بجووڵێ.","ڕاکێشانی مل: بە هێواشی سەرت بەرەو شانەکانت بچەمێنەوە.","ڕاکێشانی پشت: لەسەر کورسییەکە بە هێواشی لەشت بسووڕێنە.","کاتێک گونجاو بوو، لە جیاتی ئاسانسۆر پلیکانە بەکاربهێنە.","بە درێژاییی ڕۆژ بە ڕێکوپێکی ئاو بخۆرەوە.","دانیشتنی دروست: پشت ڕاست، شان هێمن، پێ لەسەر زەوی."]},{heading:"٤. تەندروستیی دەروونی",body:"سەلامەتیی دەروونیی فەرمانبەران:",points:["فشاری کار (Stress): هۆکارە سەرەکییەکانی بناسە.","ڕێکخستنی کات: کاتی کار و کاتی پشوو لە یەکتر جیا بکەرەوە.","قسەکردن: لەگەڵ هاوکارەکانت دەربارەی کێشەکان قسە بکە.","هەموو ڕۆژێک ١٥ خولەک لە دەرەوە پشوو بدە.","لە کاتی پشوودا مۆبایل بۆ کار بەکار مەهێنە.","ئەگەر نیشانەکان بەردەوام بوون: پەیوەندی بە پسپۆڕێکی تەندروستیی دەروونییەوە بکە."]}],media:[{kind:"video",src:"media/videos/gov_ergonomics.mp4",title:"ئێرگۆنۆمی (Ergonomics)",description:"ڕێکخستنی مێز و کورسی"},{kind:"image",src:"media/images/gov_posture.png",title:"دانیشتنی دروست",description:"وێنەیەکی ڕێنمایی"},{kind:"image",src:"media/images/gov_eye_care.png",title:"ڕێسای ٢٠-٢٠-٢٠",description:"پاراستنی چاو"}],quiz:[{question:"ڕێسای ٢٠-٢٠-٢٠ بۆ چییە؟",options:[{text:"پاراستنی گوێ",correct:!1},{text:"پاراستنی چاو",correct:!0},{text:"پاراستنی پشت",correct:!1},{text:"پاراستنی دەست",correct:!1}],explanation:"هەر ٢٠ خولەک جارێک، بۆ ماوەی ٢٠ چرکە سەیری شتێک بکە کە ٢٠ پێ (نزیکەی ٦ مەتر) دوور بێت — بۆ پاراستنی چاو (AAO)."},{question:"شاشەی کۆمپیوتەر دەبێت چەند لە چاو دوور بێت؟",options:[{text:"٢٠-٣٠ سم",correct:!1},{text:"٣٠-٤٠ سم",correct:!1},{text:"٥٠-٧٠ سم",correct:!0},{text:"١ مەتر",correct:!1}],explanation:"دووریی ٥٠-٧٠ سم (نزیکەی درێژیی باسک) گونجاوترە."},{question:"فەرمانبەر دەبێت هەر چەند خولەک جارێک لەبەر مێزەکە هەستێت و بجووڵێت؟",options:[{text:"٢٠ خولەک",correct:!1},{text:"٤٥ خولەک",correct:!0},{text:"٢ کاتژمێر",correct:!1},{text:"١ کاتژمێر",correct:!1}],explanation:"پێشنیار دەکرێت هەر ٤٥ خولەک جارێک هەستیت و کەمێک بجووڵێیت."}]},{id:11,code:"GOV-111",icon:"Waves",accent:"#2563eb",title:"لافاو و زیانەکانی ئاو",subtitle:"Flood Response & Water Damage",summary:"ئامادەباشی و وەڵامدانەوەی لافاو و زیانەکانی ئاو لە فەرمانگەکاندا",blocks:[{body:"ئاو دەتوانێت لە چەند سەرچاوەیەکەوە بگاتە فەرمانگەکان: باران و لافاوی سروشتی، تەقینی بۆریی ئاو، کێشەکانی سیستەمی فێنککەرەوە (کۆندیشن)، یان دزەکردنی ئاو لە نهۆمی سەرەوە. ئامادەباشی و هۆشیاری زیان کەم دەکەنەوە."},{heading:"١. سەرچاوەکانی ئاو لە فەرمانگەکاندا",body:"ئاو لە کوێوە دێت:",points:["باران و لافاوی سروشتی: بەتایبەتی لە ناوچە نزمەکان.","تەقینی بۆریی ئاو: بۆریی کۆن و ژەنگگرتوو.","توانەوەی بەفر: بەفر دەبێتە ئاو و دەچێتە ناو بیناکە.","دزەکردنی ئاو لە نهۆمی سەرەوە: لە تەوالێت و چێشتخانەوە.","سیستەمی فێنککەرەوە (کۆندیشن): ئاوی کۆبووەوە و دزەکردن.","تانکی ئاو: تەقین یان دزەکردنی تانکی."]},{heading:"٢. پێش لافاو — ئامادەکاری",body:"ئامادەکارییە پێویستەکان:",points:["بەڵگەنامە گرنگەکان لە نهۆمەکانی سەرەوە و لە دۆڵابی بەرزدا دابنێ.","کۆمپیوتەرەکان لەسەر زەوی دامەنێ — لانیکەم ٣٠ سم بەرزتر لە زەوی.","وایەرەکانی کارەبا لەسەر زەوی نەبن.","نەخشەی بۆرییەکان و شوێنی سەمامەی سەرەکیی ئاو بزانە.","پەمپی بەتاڵکردنەوەی ئاو (Sump Pump) ئامادە بکە.","لیستی ژمارە تەکنیکی و تەنگانەکان ئامادە بهێڵەرەوە."]},{heading:"٣. لە کاتی لافاودا",body:"ئەگەر ئاو هاتە ناو فەرمانگەکە:",points:["ئەگەر لە ناو ئاودا نەبوویت و بە سەلامەتی دەگەیتە سویچەکە، کارەبای سەرەکی ببڕە — کارەبا و ئاو پێکەوە کوشندەن.","پەیوەندی بە ١١٥ بکە و بەرپرسی بیناکە ئاگادار بکەرەوە.","هەموو فەرمانبەران بە سەلامەتی بۆ شوێنێکی بەرز دەربچن.","ئەگەر ئاوەکە کەم بوو: بەڵگەنامە و کۆمپیوتەرەکان بۆ شوێنێکی بەرز بگوازەرەوە.","مەچۆ ناو ئاوی لافاو: ١٥ سم ئاوی خێرا دەتوانێت مرۆڤ بخات و ٣٠ سم دەتوانێت ئۆتۆمبێل ڕاپێچێت؛ مەترسیی کارەبا و نەخۆشییەکانیش هەیە.","سەمامەی سەرەکیی ئاو دابخە."]},{heading:"٤. دوای لافاو",body:"دوای ئەوەی ئاوەکە کەم بووەوە:",points:["پشکنینی بینا: پێش گەڕانەوە، با شارەزایەک بیناکە بپشکنێت.","کارەبا هەڵمەکە تا تەکنیسیەن پشتڕاستی نەکاتەوە کە سەلامەتە.","پاککردنەوە لە میکرۆب (Disinfection): ئاوی لافاو پیسە و بەکتریا و نەخۆشی دەگوازێتەوە.","هەواگۆڕکێ: هەموو پەنجەرە و دەرگاکان بکەرەوە.","وێنە بگرە بۆ تۆمارکردن و بیمە.","شتە زیانلێکەوتووەکان بە سەلامەتی لابە."]}],media:[{kind:"video",src:"media/videos/gov_flood_response.mp4",title:"وەڵامدانەوەی لافاو",description:"کاتێک ئاو دێت چی بکەین"},{kind:"image",src:"media/images/gov_flood_prep.png",title:"ئامادەکاریی لافاو",description:"هەنگاو بە هەنگاو"}],quiz:[{question:"لە کاتی لافاو لە فەرمانگەدا، یەکەم کار چییە؟",options:[{text:"بەڵگەنامەکان کۆ بکەرەوە",correct:!1},{text:"کارەبای سەرەکی ببڕە (ئەگەر سەلامەت بوو)",correct:!0},{text:"وێنە بگرە",correct:!1},{text:"بە تەلەفۆن قسە بکە",correct:!1}],explanation:"کارەبا و ئاو پێکەوە مەترسیی مردن دروست دەکەن. ئەگەر لە ناو ئاودا نەبوویت و بە سەلامەتی دەگەیتە سویچەکە، یەکسەر کارەبای سەرەکی ببڕە؛ ئەگەر نا، دەربچۆ و پەیوەندی بە ١١٥ بکە."},{question:"بەڵگەنامە گرنگەکان لە فەرمانگەیەکی لەبەردەم مەترسیی لافاودا لە کوێ دابنێین؟",options:[{text:"لەسەر زەوی",correct:!1},{text:"لە نهۆمی ژێرزەوی",correct:!1},{text:"لە نهۆمەکانی سەرەوە و لە دۆڵابی بەرزدا",correct:!0},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"هەمیشە بەڵگەنامە گرنگەکان لە شوێنێکی بەرز و سەلامەتدا دابنێ."},{question:"بۆچی دوای لافاو پاککردنەوە لە میکرۆب پێویستە؟",options:[{text:"بۆ بۆنی خۆش",correct:!1},{text:"ئاوی لافاو بەکتریا و نەخۆشی دەگوازێتەوە",correct:!0},{text:"بۆ جوانی",correct:!1},{text:"پێویست نییە",correct:!1}],explanation:"ئاوی لافاو زۆر پیسە و بەکتریا و نەخۆشی دەگوازێتەوە."}]},{id:12,code:"GOV-112",icon:"FlaskConical",accent:"#65a30d",title:"مادە کیمیایی و پاککەرەوەکان",subtitle:"Chemical Safety & Cleaning Agents",summary:"بەکارهێنانی سەلامەتی مادە پاککەرەوە و کیمیاییەکان لە فەرمانگەکاندا",blocks:[{body:"فەرمانگە حکومییەکان زۆر جۆری مادەی پاککەرەوە بەکاردەهێنن. تێکەڵکردنی هەندێک لەم مادانە دەتوانێت گازی ژەهراوی و مەترسیدار دروست بکات. ناسینی مادەکان و بەکارهێنانی دروستیان ژیان ڕزگار دەکات."},{heading:"١. مادە مەترسیدارەکان لە فەرمانگەکاندا",body:"ئەم مادانە لە زۆربەی فەرمانگەکاندا هەن:",points:["کلۆر (Bleach): بۆ پاککردنەوەی تەوالێتەکان — ئەگەر لەگەڵ ترشەڵۆک (ئەسید) یان ئەمۆنیادا تێکەڵ بێت، گازی ژەهراوی دروست دەکات.","ئەمۆنیا: بۆ پاککردنەوەی پەنجەرەکان — زیان بە هەناسەدان دەگەیەنێت.","ترشەڵۆک (ئەسید): بۆ لابردنی کلس — پێست دەسووتێنێت.","تۆنەری چاپکەرەکان: تۆزێکی ورد — مەترسی بۆ سییەکان.","شلەی ڕاستکردنەوەی نووسین (Correction Fluid): ئاگر دەگرێت و هەڵمەکەی زیانبەخشە.","ترشەڵۆکی پاتری: سووتانی کیمیایی."]},{heading:"٢. ڕێسای تێکەڵنەکردن!",body:"هەرگیز ئەم مادانە تێکەڵ مەکە:",points:["کلۆر + ئەمۆنیا = گازی کلۆرامین (ژەهراوی و کوشندە).","کلۆر + ترشەڵۆک = گازی کلۆر (ژەهراوی و کوشندە).","کلۆر + سرکە (کە ترشەڵۆکە) = گازی کلۆر.","هەر مادەیەک بە تەنها بەکاربهێنە.","تەنها بە ئاو کاڵی بکەرەوە، بەپێی ڕێنماییەکانی سەر قوتووەکە — نەک بە مادەیەکی تر.","هەمیشە ڕێنماییەکانی سەر قوتووەکە (Label) بخوێنەرەوە."]},{heading:"٣. کەرەستەکانی پاراستنی کەسی (PPE)",body:"کەرەستەکانی پاراستن لە کاتی بەکارهێنانی مادەکاندا:",points:["دەستکێش: بۆ هەموو مادە کیمیاییەکان پێویستە.","ماسک: کاتێک کلۆر و مادەی بۆنتوند بەکاردەهێنیت.","چاویلکەی پاراستن: بۆ ترشەڵۆک و سپرەیەکان.","جلی پاراستن: بۆ مادە بەهێزەکان.","ئەگەر مادەکە کەوتە سەر پێست یان چاو: لانیکەم ٢٠ خولەک بە ئاوی ڕەوان بیشۆ؛ ئەگەر سووتان یان ژەهراویبوون هەبوو پەیوەندی بە ١٢٢ بکە.","هەواگۆڕکێ: لە کاتی پاککردنەوەدا پەنجەرە بکەرەوە."]},{heading:"٤. هەڵگرتن و لابردنی مادەکان",body:"ڕێساکانی هەڵگرتنی مادەکان:",points:["لە شوێنێکی قفڵدراودا دایبنێ.","دوور لە تیشکی خۆر و گەرما.","ناوی مادەکە لەسەر هەموو شووشە و قوتووەکان بنووسە.","پەڕەکانی زانیاریی سەلامەتی (SDS) ئامادە بهێڵەرەوە.","مادە بەسەرچووەکان بە ڕێگای دروست لابە — مەیڕێژە ناو بۆرییەکانی ئاوی پیس.","دوور لە خواردن و ئاوی خواردنەوە دایبنێ."]}],media:[{kind:"video",src:"media/videos/gov_chemical_safety.mp4",title:"سەلامەتیی کیمیایی",description:"بەکارهێنانی دروست"},{kind:"image",src:"media/images/gov_mixing_danger.png",title:"مەترسیی تێکەڵکردن",description:"کام مادانە نابێت تێکەڵ بکرێن"},{kind:"image",src:"media/images/gov_ppe_cleaning.png",title:"PPE بۆ پاککردنەوە",description:"کەرەستەکانی پاراستن"}],quiz:[{question:"ئەگەر کلۆر و ئەمۆنیا تێکەڵ بکەین چی ڕوودەدات؟",options:[{text:"پاککەرەوەیەکی باشتر دروست دەبێت",correct:!1},{text:"گازی کلۆرامین (ژەهراوی) دروست دەبێت",correct:!0},{text:"هیچ ڕوونادات",correct:!1},{text:"بۆنێکی خۆش دروست دەبێت",correct:!1}],explanation:"تێکەڵکردنی کلۆر و ئەمۆنیا گازی کلۆرامین دروست دەکات — مەترسیی مردنی هەیە."},{question:"ئەگەر مادەیەکی کیمیایی کەوتە سەر پێست، چی بکەین؟",options:[{text:"بە دەستەسڕ پاکی بکەرەوە",correct:!1},{text:"لانیکەم ٢٠ خولەک بە ئاو بیشۆ",correct:!0},{text:"کرێمی لێ بدە",correct:!1},{text:"هیچ مەکە",correct:!1}],explanation:"یەکسەر لانیکەم ٢٠ خولەک بە ئاوی ڕەوان بیشۆ و جلە پیسبووەکان دابکەنە؛ ئەگەر سووتان هەبوو پەیوەندی بە ١٢٢ بکە."},{question:"مادە پاککەرەوەکان لە فەرمانگەدا لە کوێ دابنێین؟",options:[{text:"لەسەر مێز",correct:!1},{text:"لە نزیک خواردن",correct:!1},{text:"لە شوێنێکی قفڵدراو و دوور لە گەرما",correct:!0},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"لە شوێنێکی قفڵدراو، دوور لە گەرما و خواردن دایبنێ."}]},{id:13,code:"GOV-113",icon:"ArrowUpDown",accent:"#4f46e5",title:"سەلامەتیی ئاسانسۆر و پلیکانە",subtitle:"Elevator & Stairway Safety",summary:"بەکارهێنانی سەلامەتی ئاسانسۆر و ڕێگریکردن لە کەوتن لەسەر پلیکانە",blocks:[{body:"ئاسانسۆر و پلیکانەکانی بینا لە شوێنە باوەکانی ڕووداون لە بینا حکومییەکاندا. کەوتن لەسەر پلیکانە یەکێکە لە باوترین ڕووداوەکانی شوێنی کار، و گیرخواردن لە ناو ئاسانسۆردا بارودۆخێکی جددییە. زانینی ڕێساکان مەترسی کەم دەکاتەوە."},{heading:"١. سەلامەتیی ئاسانسۆر",body:"ڕێساکانی بەکارهێنانی ئاسانسۆر:",points:["ئەگەر ئاسانسۆرەکە دواکەوت، ئارام بگرە — دوگمەکە چەند جار دامەگرە.","دەرگای ئاسانسۆر بە دەست مەکەرەوە — با خۆی بکرێتەوە.","لە باری ڕێگەپێدراو (کە لەسەری نووسراوە) زیاتر بار مەکە.","لە کاتی بڕانی کارەبادا بەکاری مەهێنە.","لە کاتی ئاگر و بوومەلەرزەدا بەکاری مەهێنە — تەنها پلیکانە.","بزانە دوگمەی تەنگانە لە کوێیە."]},{heading:"٢. گیرخواردن لە ناو ئاسانسۆردا",body:"ئەگەر لە ناو ئاسانسۆردا گیرت خوارد:",points:["ئارام بە — مەترسە.","دوگمەی تەنگانە دابگرە.","تەلەفۆنی ناو ئاسانسۆرەکە بەکاربهێنە.","ئەگەر تۆڕی مۆبایل هەبوو، پەیوەندی بە ١١٥ بکە.","هەوڵی کردنەوەی دەرگاکە یان دەرچوون مەدە — مەترسیدارە.","چاوەڕێ بکە تا تەکنیسیەن یان تیمی ١١٥ دەگات — هەوا لە ناو ئاسانسۆردا تەواو نابێت."]},{heading:"٣. سەلامەتیی پلیکانە",body:"ڕێگریکردن لە کەوتن لەسەر پلیکانە:",points:["هەمیشە دەسکی پلیکانە (Handrail) بگرە.","سەیری بەردەم پێیەکانت بکە — مۆبایل بەکار مەهێنە.","پلە بە پلە — باز مەدە.","لەسەر پلیکانەی تەڕ بە ئاگاییەوە بڕۆ.","کاتێک بار هەڵدەگریت، دەستێکت ئازاد بهێڵەرەوە بۆ گرتنی دەسکەکە.","ڕووناکیی پلیکانەکان دەبێت باش بێت — گڵۆپە سووتاوەکان بگۆڕە."]},{heading:"٤. پشکنین و چاکردنەوە",body:"پشکنینە ڕێکوپێکەکان:",points:["ئاسانسۆر: چاکردنەوەی مانگانە لەلایەن کۆمپانیایەکی شارەزاوە و پشکنینی ساڵانە لەلایەن لایەنێکی پەسەندکراوەوە.","بڕوانامەی پشکنین لە ناو ئاسانسۆرەکەدا هەڵبواسە.","ڕووناکیی تەنگانەی پلیکانەکان بپشکنە.","پلیکانە شکاوەکان یەکسەر چاک بکەرەوە.","لە شوێنە خلیسکەکان نیشانەی ئاگادارکردنەوە دابنێ.","پلیکانەکان پاک بهێڵەرەوە — هیچ شتێک لەسەر پلیکانەکان دامەنێ."]}],media:[{kind:"video",src:"media/videos/gov_elevator_safety.mp4",title:"سەلامەتیی ئاسانسۆر",description:"بەکارهێنانی دروست و گیرخواردن لە ناویدا"},{kind:"image",src:"media/images/gov_stair_safety.png",title:"سەلامەتیی پلیکانە",description:"ڕێساکانی ڕێگریکردن لە کەوتن"}],quiz:[{question:"لە کاتی ئاگرکەوتنەوەدا، بۆ دەرچوون چی بەکاربهێنین؟",options:[{text:"ئاسانسۆر",correct:!1},{text:"پلیکانەکانی بیناکە",correct:!0},{text:"هیچ جیاوازییەک نییە",correct:!1},{text:"پەنجەرە",correct:!1}],explanation:"لە کاتی ئاگر و بوومەلەرزەدا هەرگیز ئاسانسۆر بەکار مەهێنە — تەنها بە پلیکانەکاندا دەربچۆ."},{question:"ئەگەر لە ناو ئاسانسۆردا گیرت خوارد، چی دەکەیت؟",options:[{text:"هەوڵی کردنەوەی دەرگاکە بدە",correct:!1},{text:"بە ترسەوە هاوار بکە",correct:!1},{text:"دوگمەی تەنگانە دابگرە و ئارام بە",correct:!0},{text:"باز بدە",correct:!1}],explanation:"ئارام بە و دوگمەی تەنگانە دابگرە. هەوڵی کردنەوەی دەرگاکە مەدە."},{question:"بۆ ڕێگریکردن لە کەوتن لەسەر پلیکانە، چی بکەین؟",options:[{text:"باز بدە",correct:!1},{text:"مۆبایل بەکاربهێنە",correct:!1},{text:"دەسکی پلیکانە بگرە و سەیری بەردەم پێیەکانت بکە",correct:!0},{text:"چاوەکانت دابخە",correct:!1}],explanation:"هەمیشە دەسکی پلیکانە بگرە و سەیری بەردەم پێیەکانت بکە."}]},{id:14,code:"GOV-114",icon:"Network",accent:"#e11d48",title:"بەڕێوەبردنی قەیرانەکان",subtitle:"Crisis Management & ICS",summary:"دامەزراندنی تیمی بەڕێوەبردنی قەیرانەکان و سیستەمی فەرماندەیی ڕووداو (ICS)",blocks:[{body:"هەر فەرمانگەیەکی حکومی دەبێت تیمێکی بەڕێوەبردنی قەیرانەکانی (Crisis Management Team) هەبێت. قەیران دەتوانێت ئاگر، بوومەلەرزە، لافاو، هێرشێکی ئەمنی یان تەنانەت هێرشێکی سایبەری بێت. سیستەمی فەرماندەیی ڕووداو (ICS) ئامرازێکی نێودەوڵەتییە بۆ بەڕێوەبردنی هەر ڕووداوێک."},{heading:"١. تیمی بەڕێوەبردنی قەیرانەکان (CMT)",body:"پێکهاتەی تیم:",points:["سەرۆکی تیم (Crisis Commander): بڕیاردەر و ئاراستەکەر.","بەرپرسی کارەکان (Operations): ڕێکخستنی چالاکییەکان.","بەرپرسی ڕاگەیاندن: پەیوەندی لەگەڵ لایەنە دەرەکییەکان و میدیا.","بەرپرسی لۆجستیک: پێداویستی و ئامێر.","بەرپرسی داتا: تۆمارکردنی ڕووداوەکان.","بەرپرسی فریاکەوتنی سەرەتایی: یارمەتیدانی برینداران."]},{heading:"٢. سیستەمی فەرماندەیی ڕووداو (ICS)",body:"ICS (Incident Command System):",points:["لە ئەمریکا دروستکراوە و ئێستا لە زۆر وڵاتدا بەکاردەهێنرێت.","یەک فەرماندەی ڕووداو — زنجیرەی فەرماندەیی ڕوونە.","دیاریکردنی ئەرکەکان: هەر کەسێک ئەرکی خۆی دەزانێت و بە یەک سەرپەرشتیارەوە بەستراوە.","ڕاگەیاندنی یەکگرتوو: یەک کەناڵی پەیوەندی و زمانی سادە.","ڕێکخستنی نەرم (Modular): ڕێکخستنەکە بەپێی قەبارەی ڕووداوەکە گەورە یان بچووک دەبێت.","ڕاپۆرت: نوێکردنەوەی ڕاپۆرتەکان لە کاتە دیاریکراوەکاندا."]},{heading:"٣. هەنگاوەکانی وەڵامدانەوەی قەیران",body:"ڕێکاری گشتی:",points:["١. ئاگادارکردنەوە: سیستەمی ئاگادارکردنەوە چالاک بکە.","٢. هەڵسەنگاندن: بزانە چی ڕوویداوە و قەبارەکەی چەندە.","٣. چالاککردن: تیمی CMT کۆ بکەرەوە.","٤. بەڕێوەبردن: بڕیار بدە و جێبەجێی بکە.","٥. ڕاگەیاندن: هەموو لایەنەکان ئاگادار بکەرەوە.","٦. گەڕانەوە: پلانی گەڕانەوە بۆ کاری ئاسایی جێبەجێ بکە."]},{heading:"٤. ڕاهێنان و تاقیکردنەوە",body:"ئامادەباشیی بەردەوام:",points:["هەر ٣ مانگ جارێک ڕاهێنانی سەر مێز (Tabletop Exercise).","هەر ٦ مانگ جارێک ڕاهێنانی تەواو (Full-Scale Drill).","نوێکردنەوەی پلانی قەیران هەموو ساڵێک.","تاقیکردنەوەی سیستەمی ڕاگەیاندن.","هاوکاری لەگەڵ بەرگریی شارستانی (١١٥) و پۆلیس (١٠٤).","دوای هەر ڕاهێنانێک هەڵسەنگاندن بکە و کارەکە باشتر بکە."]}],media:[{kind:"video",src:"media/videos/gov_crisis_management.mp4",title:"بەڕێوەبردنی قەیرانەکان",description:"سیستەمی ICS و تیمی CMT"},{kind:"image",src:"media/images/gov_ics_chart.png",title:"هێڵکاریی ICS",description:"پێکهاتەی فەرماندەیی"}],quiz:[{question:"لە سیستەمی ICS دا، چەند فەرماندەی ڕووداو هەن؟",options:[{text:"٣",correct:!1},{text:"٥",correct:!1},{text:"١ (یەک)",correct:!0},{text:"١٠",correct:!1}],explanation:"لە ICS دا یەک فەرماندەی ڕووداو هەیە، بۆ ئەوەی زنجیرەی فەرماندەیی ڕوون بێت. ئەگەر چەند لایەنێک بەشدار بن، فەرماندەیی یەکگرتوو (Unified Command) بە یەک پلان کار دەکات."},{question:"بەپێی ئەم بەرنامەیە، ڕاهێنانی سەر مێز (Tabletop) هەر چەند جار جارێک پێویستە؟",options:[{text:"هەموو ساڵێک",correct:!1},{text:"هەر ٦ مانگ جارێک",correct:!1},{text:"هەر ٣ مانگ جارێک",correct:!0},{text:"تەنها یەک جار",correct:!1}],explanation:"ئەم بەرنامەیە پێشنیار دەکات هەر ٣ مانگ جارێک ڕاهێنانی سەر مێز ئەنجام بدرێت."},{question:"یەکەم هەنگاو لە وەڵامدانەوەی قەیراندا چییە؟",options:[{text:"بەڕێوەبردن",correct:!1},{text:"ڕاگەیاندن",correct:!1},{text:"ئاگادارکردنەوە و چالاککردنی سیستەمی ئاگادارکردنەوە",correct:!0},{text:"گەڕانەوە",correct:!1}],explanation:"یەکەم هەنگاو: ئاگادارکردنەوە — سیستەمی ئاگادارکردنەوە چالاک بکە."}]},{id:15,code:"GOV-115",icon:"Megaphone",accent:"#c026d3",title:"ڕاگەیاندن لە کاتی تەنگانەدا",subtitle:"Emergency Communication",summary:"سیستەمی ڕاگەیاندن و ئاگادارکردنەوە لە کاتی ڕووداوەکاندا",blocks:[{body:"لە کاتی ڕووداوەکاندا، ڕاگەیاندنی دروست و خێرا ژیان ڕزگار دەکات. لە زۆر ڕووداودا، نەبوونی ڕاگەیاندنێکی باش ژمارەی قوربانییەکانی زیاد کردووە. هەر فەرمانگەیەکی حکومی دەبێت سیستەمێکی ڕاگەیاندنی بەهێزی هەبێت."},{heading:"١. سیستەمەکانی ئاگادارکردنەوە",body:"چەند سیستەمێک هەن:",points:["سیرینی ناوخۆیی: زەنگی ئاگر و تەنگانە.","سیستەمی بڵندگۆ (PA System): بۆ ناردنی پەیام بۆ هەموو نهۆمەکان.","نامەی مۆبایل (SMS Group): بۆ فەرمانبەران.","ئیمەیڵی خێرا: بۆ ئاگادارکردنەوە فەرمییەکان.","گرووپەکانی واتسئاپ و تێلیگرام: بۆ هەماهەنگیی خێرا.","ڕادیۆی دوولایەنە (Walkie-Talkie): بۆ تیمی تەنگانە."]},{heading:"٢. زنجیرەی ڕاگەیاندن",body:"کێ پەیامەکە دەنێرێت:",points:["١. ئاگادارکەرەوە: ئەو کەسەی ڕووداوەکەی بینیوە — یەکسەر پەیوەندی بە ١١٥ دەکات (و ١٢٢ ئەگەر بریندار هەبوون).","٢. بەرپرسی نهۆم: فەرمانبەری بەرپرس لە نهۆم و ژوورەکان.","٣. فەرماندەی قەیران: بڕیاردان و ئاراستەکردن.","٤. بەرپرسی ڕاگەیاندن: پەیوەندی لەگەڵ ١١٥ و لایەنە دەرەکییەکان.","٥. بەڕێوەبەری فەرمانگە: ئاگادارکردنەوەی ئاستی باڵاتر.","هەموو پەیامەکان دەبێت ورد بن و زانیاریی تەواویان تێدا بێت."]},{heading:"٣. ناوەڕۆکی پەیامی تەنگانە",body:"پەیامێکی باش ئەمانەی تێدایە:",points:["شوێن: لە کوێ ڕوویدا (بینا، نهۆم، ژوور).","چی: چی ڕوویدا (ئاگر، بوومەلەرزە، هێرش...)","کەسەکان: چەند کەس بریندار بوون یان گیریان خواردووە.","مەترسی: ئایا مەترسییەکی بەردەوام هەیە؟","پێداویستی: چ یارمەتییەک پێویستە.","پەیوەندی: ژمارەی تەلەفۆنەکەت بۆ پەیوەندیکردن."]},{heading:"٤. ڕاگەیاندن لەگەڵ لایەنە دەرەکییەکان",body:"پەیوەندی لەگەڵ لایەنە دەرەکییەکان:",points:["١١٥ — بەرگریی شارستانی: ئاگر و ڕزگارکردن.","١٢٢ — ئەمبولانس: برینداری و نەخۆشی.","١٠٤ — پۆلیس: بارودۆخە ئەمنییەکان.","میدیا: تەنها بەرپرسی ڕاگەیاندن قسە دەکات.","خێزانی فەرمانبەران: ئاگادارکردنەوە بە ئاسانترین ڕێگا.","بەڕێوەبەرایەتیی گشتی: ڕاپۆرتی فەرمی."]},{heading:"٥. تاقیکردنەوەی سیستەم",body:"پشکنینی بەردەوام:",points:["هەموو مانگێک سیرینی ناوخۆیی تاقی بکەرەوە.","هەموو هەفتەیەک پەیامێکی تاقیکاری بۆ گرووپەکە بنێرە.","پاتری و مەودای ڕادیۆ دوولایەنەکان بپشکنە.","لیستی ژمارەکانی تەنگانە نوێ بکەرەوە.","دوای هەر ڕاهێنانێک سیستەمی ڕاگەیاندن هەڵبسەنگێنە.","پلانی جێگرەوە: ئەگەر سیستەمێک کاری نەکرد، جێگرەوەکەی چییە؟"]}],media:[{kind:"video",src:"media/videos/gov_emergency_comm.mp4",title:"ڕاگەیاندنی تەنگانە",description:"سیستەمی ڕاگەیاندن و زنجیرەکەی"},{kind:"image",src:"media/images/gov_comm_chain.png",title:"زنجیرەی ڕاگەیاندن",description:"کێ پەیوەندی بە کێوە دەکات"},{kind:"image",src:"media/images/gov_message_template.png",title:"نموونەی پەیام",description:"ناوەڕۆکی پەیامی دروست"}],quiz:[{question:"لە کاتی تەنگانەدا، کام سیستەم خێراترینە بۆ ئاگادارکردنەوەی هەموو نهۆمەکان؟",options:[{text:"ئیمەیڵ",correct:!1},{text:"واتسئاپ",correct:!1},{text:"سیستەمی بڵندگۆ (PA)",correct:!0},{text:"نامەی کاغەزی",correct:!1}],explanation:"سیستەمی PA خێراترینە چونکە یەکسەر لە هەموو نهۆمەکاندا دەبیسترێت."},{question:"پەیامی تەنگانە دەبێت چ زانیارییەکی تێدا بێت؟",options:[{text:"تەنها شوێن",correct:!1},{text:"تەنها ژمارەی برینداران",correct:!1},{text:"شوێن، چی ڕوویدا، کەسەکان، مەترسی، پێداویستی",correct:!0},{text:"تەنها ژمارە ١١٥",correct:!1}],explanation:"پەیامی تەواو: شوێن + چی ڕوویدا + کەسەکان + مەترسی + پێداویستی + ژمارەی پەیوەندی."},{question:"لە کاتی قەیراندا، کێ مۆڵەتی قسەکردنی لەگەڵ میدیا هەیە؟",options:[{text:"هەر فەرمانبەرێک",correct:!1},{text:"تەنها بەرپرسی ڕاگەیاندن",correct:!0},{text:"سەردانکەر",correct:!1},{text:"تەنها پۆلیس",correct:!1}],explanation:"تەنها بەرپرسی ڕاگەیاندن مۆڵەتی قسەکردنی لەگەڵ میدیا هەیە، بۆ ئەوەی زانیاریی هەڵە بڵاو نەبێتەوە."}]},{id:16,code:"GOV-116",icon:"Heart",accent:"#db2777",title:"فریاکەوتنی سەرەتایی و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانی تەواو لەسەر فریاکەوتنی سەرەتایی، CPR و وەڵامدانەوەی تەنگانە لە فەرمانگەکاندا",blocks:[{body:"فریاکەوتنی سەرەتایی (First Aid) ئەو یارمەتییە سەرەتاییەیە کە پێش گەیشتنی تیمە پزیشکییەکان بە کەسی بریندار یان نەخۆش دەدرێت. لە فەرمانگەکاندا مەترسیی ئاگر، بوومەلەرزە و نەخۆشیی کتوپڕ هەیە. هەر فەرمانبەرێک دەبێت بزانێت چۆن CPR ئەنجام بدات، خوێنبەربوون ڕابگرێت و بریندارێک بپارێزێت تا ئەمبولانس (١٢٢) دەگات."},{heading:"١. CPR — زیندووکردنەوەی دڵ و سی",body:"CPR ڕێکارێکی ڕزگارکردنی ژیانە کاتێک دڵ یان هەناسەدانی مرۆڤ ڕادەوەستێت:",points:["١. سەلامەتیی شوێن: ئایا شوێنەکە سەلامەتە؟ (کارەبا، ئاگر یان گاز نییە؟)","٢. وەڵامدانەوە: بە هێواشی شانەکانی ڕابوەشێنە و بە دەنگی بەرز بپرسە: «باشیت؟ گوێت لە منە؟»","٣. پەیوەندی بە ١٢٢ بکە: ئەگەر وەڵامی نەدایەوە و بە دروستی هەناسەی نەدا، یەکسەر پەیوەندی بە ١٢٢ بکە و AED بهێنە یان داوای بکە.","٤. فشاری سنگ: ٣٠ فشار لە ناوەڕاستی سنگ — قووڵی ٥-٦ سم، خێرایی ١٠٠-١٢٠ فشار لە خولەکێکدا.","٥. هەناسە: سەری بەرەو دواوە ببە و چەناگەی بەرز بکەرەوە، لووتی بگرە و ٢ هەناسەی ١ چرکەیی بدە؛ ئەگەر ڕاهێنانت نەبینیوە، تەنها فشاری سنگ بکە.","٦. بەردەوامی (٣٠:٢): تا تیمی ئەمبولانس (١٢٢) دەگات.","٧. AED: ئەگەر هەبوو، هەڵیبکە، پەدەکان لەسەر سنگی ڕووت دابنێ و گوێ لە فەرمانە دەنگییەکان بگرە."]},{heading:"٢. ڕاگرتنی خوێنبەربوون",body:"خوێنبەربوونی سەخت دەتوانێت بە خێرایی ببێتە هۆی مردن:",points:["فشاری ڕاستەوخۆ: پارچەیەکی پاک لەسەر برینەکە دابنێ و بە هێز و بەبێ وەستان فشار بدە؛ ئەگەر قوماشەکە بە خوێن تەڕ بوو، لای مەبە — یەکێکی تر لەسەری دابنێ.","پڕکردنەوەی برین (Wound Packing): ئەگەر برینەکە قووڵ بوو (وەک لە ڕان، بنباڵ یان مل)، پەڕۆی پاکی برینپێچ بخە ناو برینەکە و بە هێز فشار بدە.","تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونی مەترسیدار لە دەست یان قاچ زوو بەکاری بهێنە، ٥-٧ سم لە سەرووی برینەکەوە؛ کاتی دانانەکەی بنووسە و هەرگیز شلی مەکەرەوە.","شتی چەقیو: ئەگەر ئاسن یان شووشە لە ناو برینەکەدا بوو — دەری مەهێنە! لە دەوریدا جێگیری بکە و پەیوەندی بە ١٢٢ بکە."]},{heading:"٣. چارەسەری سووتان",body:"سووتان لە فەرمانگەکاندا بەهۆی گەرما، مادە کیمیاییەکان و کارەباوە ڕوودەدات:",points:["سووتانی گەرمی: ٢٠ خولەک ئاوی فێنکی ڕەوان (نەک سەهۆڵ!) بەسەر شوێنی سووتاوەکەدا بڕژێنە.","سووتانی کیمیایی: ٢٠ خولەک بە ئاوی ڕەوانی زۆر بیشۆ.","سووتانی کارەبا: یەکەم جار کارەبا ببڕە! دواتر وەک سووتانی گەرمی سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە.","بڵقەکانی سووتان مەتەقێنە؛ ڕۆن، مەڵهەم یان مەعجوونی ددان بەکار مەهێنە."]},{heading:"٤. شکان و برینەکانی بڕبڕەی پشت",body:"لە کاتی کەوتندا:",points:["جێگیرکردن (Splinting): ئەندامە بریندارەکە مەجووڵێنە — بە دارێک یان کارتۆنێک جێگیری بکە.","پاراستنی بڕبڕەی پشت: ئەگەر کەسێک لە بەرزییەوە کەوت، مەیجووڵێنە — بە جێگیری ڕایبگرە و پەیوەندی بە ١٢٢ بکە. تەنها ئەگەر شوێنەکە مەترسیدار بێت (ئاگر، هاتوچۆ، ڕووخان، گاز، بەرزبوونەوەی ئاو) بیجووڵێنە، و سەر، مل و پشتی لەسەر یەک هێڵ ڕابگرە؛ ئەگەر پێویستی بە CPR هەبێت، لەسەر پشت لەسەر ڕووێکی ڕەق پاڵی بخە. لەسەر لا (Recovery Position) دایمەنێ.","ساردکردنەوە: سەهۆڵ لە پارچە قوماشێکدا بپێچە و لەسەر شوێنی ئازارەکە دایبنێ (نەک ڕاستەوخۆ لەسەر پێست)."]},{heading:"٥. کارەباگرتن",body:"کارەبا دەتوانێت دڵ ڕابگرێت:",points:["یەکسەر کارەبا ببڕە! تا کارەبا نەبڕدرێت دەست لە بریندارەکە مەدە.","ئەگەر نەتتوانی کارەبا ببڕیت و کارەباکە کارەبای ئاسایی بینا بوو (ڤۆڵتیجی نزم): بە دارێکی وشک یان پلاستیک وایەرەکەی لێ دوور بخەرەوە؛ لە ڤۆڵتیجی بەرزدا دوور بمێنەرەوە و پەیوەندی بە ١١٥ بکە.","هەموو ئەو کەسانەی کارەبا لێیان داوە دەبێت بچنە نەخۆشخانە — پەیوەندی بە ١٢٢ بکە؛ ئەگەر هەناسەی نەدا، CPR دەست پێ بکە."]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"CPR و فریاکەوتنی سەرەتایی",description:"ڕاهێنانی CPR بۆ فەرمانبەران"}],quiz:[{question:"لە CPR دا، دەبێت چەند فشاری سنگ لە خولەکێکدا بێت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"دەبێت ١٠٠-١٢٠ فشار لە خولەکێکدا بێت (AHA 2025)."},{question:"ئەگەر شتێکی تیژ لە ناو برینەکەدا بوو، چی دەکەیت؟",options:[{text:"دەری دەهێنم",correct:!1},{text:"لە شوێنی خۆی بەجێی دەهێڵم و پەیوەندی بە ١٢٢ دەکەم",correct:!0},{text:"دەستم لادەبەم و هیچ ناکەم",correct:!1},{text:"بە ئاو دەیشۆم",correct:!1}],explanation:"دەرهێنانی شتەکە خوێنبەربوونەکە زیاتر دەکات؛ لە دەوریدا جێگیری بکە و پەیوەندی بە ١٢٢ بکە."},{question:"ئەگەر کارەبا لە کەسێک بدات، یەکەم کار چییە؟",options:[{text:"دەستی دەگرم",correct:!1},{text:"CPR ئەنجام دەدەم",correct:!1},{text:"کارەباکە دەبڕم",correct:!0},{text:"ئاوی پێدا دەکەم",correct:!1}],explanation:"یەکەم جار دەبێت کارەبا ببڕدرێت، بۆ ئەوەی خۆت نەبیتە قوربانی."}]},{id:17,code:"GOV-117",icon:"FlameKindling",accent:"#dc2626",title:"پۆلێنکردنی جۆرەکانی ئاگر",subtitle:"Fire Classification — NFPA 10 / BS EN 2",summary:"پۆلێنکردنی نێودەوڵەتیی جۆرەکانی ئاگر و هەڵبژاردنی ئاگرکوژێنەرەوەی گونجاو",blocks:[{body:"پۆلێنکردنی ئاگر بنەمای کاری بەرگریی شارستانییە. NFPA 10 (ستانداردی ئەمریکی) و EN 2 (ستانداردی ئەوروپی) دوو سیستەمی سەرەکین، و دەبێت هەمیشە بڵێین مەبەستمان کام سیستەمە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. هەڵبژاردنی ئاگرکوژێنەرەوەی هەڵە دەتوانێت ئاگرەکە گەورەتر بکات یان ببێتە هۆی برینداربوون. ئەم وانەیە هەر پۆلێک بەپێی ستانداردە نێودەوڵەتییەکان ڕوون دەکاتەوە."},{heading:"١. پۆلی A — مادە ڕەقەکان (Solid Combustibles)",body:"مادە ڕەقە ئۆرگانییەکان کە خۆڵەمێش بەجێ دەهێڵن:",points:["سووتەمەنی: دار، کاغەز، قوماش، پلاستیک، لاستیک، زبڵ.","پلەی خۆهەڵگیرسان: کاغەز نزیکەی ٢١٨-٢٤٦°C.","تایبەتمەندی: خۆڵەمێش و پشکۆ بەجێ دەهێڵێت و ئاگر دەتوانێت لە قووڵاییی مادەکەدا بمێنێتەوە.","ئاگرکوژێنەرەوە: ئاو، تۆزی ABC، کەف — لەیبڵ (Label) و نیشانەکانی پۆل بخوێنەرەوە (ڕەنگ پۆلی ئاگر نییە).","لە فەرمانگەکاندا: زۆربەی مادە سووتەمەنییەکان کاغەز، فایل و کەلوپەلی ژوورن.","ستاندارد: NFPA 10، EN 2.","ڕاهێنان: ئاگرکوژێنەرەوە تەنها بەکاربهێنە ئەگەر هەموو ئەمانە ڕاست بن: ئاگرەکە بچووک و تازە دەستی پێکردبێت، ئاگرکوژێنەرەوەکە گونجاو بێت، ڕێگای دەرچوون لە پشتتەوە بێت، ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت، تۆ ڕاهێنراو بیت، و هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت. پاشان ڕێکاری PASS: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە و سەری لوولەکە ئاراستەی بنی ئاگرەکە بکە؛ ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەربچۆ و دەرگاکە دابخە."]},{heading:"٢. پۆلی B — شلە سووتەمەنییەکان (Flammable Liquids)",body:"ئەو شلانەی لە پلەی گەرمیی ئاساییدا هەڵمی سووتەمەنی دروست دەکەن (لە NFPA دا گازە سووتەمەنییەکانیش دەگرێتەوە):",points:["سووتەمەنی: بەنزین، گازۆیل (Diesel)، نەوتی سپی، ئەلکهول، تینەر، بۆیە.","خاڵی هەڵگیرسان (Flash Point)، بەپێی جۆری سووتەمەنی: بەنزین نزیکەی −٤٣°C، گازۆیل نزیکەی ٥٢-٩٦°C.","تایبەتمەندی: هەڵمی شلەکە دەسووتێت، نەک خودی شلەکە.","ئاگرکوژێنەرەوە بۆ شلەکان: کەف، CO₂ یان تۆزی ABC؛ بۆ ئەلکهول و شلە جەمسەرییەکانی تر (Polar Solvents): CO₂، تۆزی ABC یان کەفی بەرگەگری ئەلکهول (AR Foam)، چونکە کەفی ئاسایی لەسەریان تێکدەچێت. ئاگری گاز (گازی LPG یان گازی سروشتی): گرنگترین شت ڕاگرتنی گازەکەیە؛ کەسێکی شارەزا سەمامەی گاز دادەخات تەنها ئەگەر گەیشتن پێی سەلامەت بێت. ئەگەر گازەکە بە سەلامەتی ڕانەگیرێت، ئاگری گازەکە مەکوژێنەرەوە: گازی نەسووتاو کۆ دەبێتەوە و دەتوانێت بتەقێتەوە. ئەگەر سەلامەت نەبوو، هەمووان دەربهێنە، ئاگادار بکەرەوە و پەیوەندی بە ١١٥ەوە بکە. کەف هەڵبژاردەی گشتی نییە بۆ ئاگری گاز.","ئاو بە لوولە بەسەر شلەی سووتاودا مەڕێژە: شلە سووتاوەکە دەپژێنێت و بڵاوی دەکاتەوە (Slop-over / Boil-over). BLEVE شتێکی ترە: تەقینەوەی دەفرێکی ژێر پەستانە دوای گەرمبوون، و ساردکردنەوەی دەفرەکە بە ئاو لە دوورەوە دەتوانێت یارمەتیدەر بێت بۆ ڕێگریکردنی؛ ئەمە کاری تیمی ١١٥ە، و هەموو کەسانی تر شوێنەکە چۆڵ دەکەن.","لە فەرمانگەکاندا: کۆگاکانی سووتەمەنیی موەلیدە و ئۆتۆمبێلەکانی خزمەتگوزاری.","ستاندارد: NFPA 30 (Flammable and Combustible Liquids Code).","ڕێکار: ئۆکسجین ببڕە (خنکاندن / Smothering)، نەک تەنها ساردکردنەوە."]},{heading:"٣. پۆلی C لە NFPA — ئامێرە کارەباییە کارەبادارەکان (Energized Electrical)",body:"ئاگری ئامێرە کارەباییەکان کاتێک کارەبایان تێدایە:",points:["سووتەمەنی: کۆمپیوتەر، سێرڤەر، پلاک، تابلۆکانی کارەبا.","گەرمیی کەوانەی کارەبا (Arc Flash): دەگاتە نزیکەی ١٩٤٠٠°C (٣٥٠٠٠°F) — نزیکەی ٤ جار گەرمتر لە ڕووی خۆر (OSHA).","ئاگرکوژێنەرەوە: CO₂، تۆزی ABC، مادەی پاک (Clean Agent) وەک FK-5-1-12.","ئاو و کەف لەسەر ئامێرە کارەباییە کارەبادارەکان بەکار مەهێنە، مەگەر لەسەر لەیبڵەکە پۆلی C یان نیشانەی تاقیکردنەوەی کارەبایی هەبێت (وەک هەندێک ئاگرکوژێنەرەوەی Water Mist) — مەترسیی شۆکی کارەبایی کوشندە.","یەکەم: ئەگەر گەیشتن بە تابلۆکە سەلامەت بوو بەبێ ئەوەی بە لای ئاگرەکەدا تێپەڕیت، کارەبا لە تابلۆکەوە ببڕە؛ پاشان ئاگرەکە بەپێی ئەو مادەیەی دەسووتێت بکوژێنەرەوە.","ستاندارد: NFPA 70E (Electrical Safety in the Workplace).","لە ژوورەکانی ICT: مادە پاکەکان باشترن — زیان بە ئامێرە گرانبەهاکان ناگەیەنن.","تێبینی: لە EN 2 دا پۆلی C گازەکانە، نەک کارەبا؛ لە ئەوروپا ئاگری کارەبایی پۆلێکی جیا نییە، و پۆلی E (کارەبا) تەنها لە ئوسترالیا بەکاردەهێنرێت."]},{heading:"٤. پۆلی D — کانزا سووتەمەنییەکان (Combustible Metals)",body:"کانزا سووتەمەنییەکان — یەکێک لە مەترسیدارترین جۆرەکان:",points:["سووتەمەنی: مەگنیسیۆم، تیتانیۆم، سۆدیۆم، پۆتاسیۆم، لیتیۆمی کانزایی.","گەرمی: مەگنیسیۆم بە پلەی گەرمیی نزیکەی ٣١٠٠°C (٥٦١٠°F) دەسووتێت.","هەرگیز ئاو نا! ئاو + مەگنیسیۆم = هایدرۆجین و تەقینەوە.","هەرگیز CO₂ نا! مەگنیسیۆم لە ناو CO₂ یشدا دەسووتێت و ئاگرەکە زیاد دەبێت.","تەنها: ئاگرکوژێنەرەوە یان مادەیەک کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت (تۆزەکانی پۆلی D وەک کلۆریدی سۆدیۆم یان گرافایت)؛ مادەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە (بۆ نموونە، لیتیۆم پێویستی بە مادەیەکی تایبەت بە لیتیۆم هەیە). هەرگیز تۆزی ئاسایی یان کەف نا. لمی وشک تەنها ئەگەر پلانی ئاگری شوێنەکە یان SDS ی کانزاکە ناوی هێنابێت و تەواو وشک بێت.","لە فەرمانگەکاندا: تاقیگە کیمیاییەکان و شوێنەکانی کارکردن لەسەر کانزا. پاترییە ئاساییەکانی لیتیۆم-ئایۆن لیتیۆمی کانزاییان تێدا نییە، و بۆ ئەوان ساردکردنەوە بە ئاو پێشنیار دەکرێت.","ستاندارد: NFPA 484 (Combustible Metals).","یەکسەر پەیوەندی بە ١١٥ بکە — تیمێکی تایبەت پێویستە."]},{heading:"٥. پۆلی F (EN 2) / پۆلی K (NFPA) — ڕۆنی چێشتلێنان (Cooking Oils)",body:"ڕۆن و چەوریی چێشتلێنان — یەکێک لە باوترین ئاگرەکانی چێشتخانە:",points:["سووتەمەنی: ڕۆنی چێشتلێنان (ڕووەکی و ئاژەڵی) و چەوری.","پلەی خۆهەڵگیرسان: بە گشتی زیاتر لە ٣٤٠°C، بەپێی جۆری ڕۆنەکە.","ئاگرکوژێنەرەوە: مادەی تەڕ (Wet Chemical) — خوێیەکانی پۆتاسیۆم؛ بۆ ڕۆن و چەوریی چێشتلێنان دروستکراوە، و زۆرێکیان بۆ پۆلی A یش گونجاون، بۆیە لەیبڵەکە بخوێنەرەوە و بەپێی لەیبڵەکە بەکاری بهێنە (لە بەریتانیا پارچەیەکی زەردی BS 7863 ی لەسەرە).","هەرگیز ئاو نا! ئاو لە ناو ڕۆنی گەرمدا بە خێرایی دەبێتە هەڵم و ڕۆنی سووتاو بە هێز دەپژێنێت (تۆپەڵە ئاگر).","تۆزی ABC بۆ ڕۆنی چێشتلێنان گونجاو نییە — ئاگرەکە دەتوانێت دیسان هەڵبگیرسێتەوە.","ڕێکار: ئەگەر ئاگرەکە بچووک بوو، گەرماکە ببڕە و سەرقاپێک یان بەتانیی ئاگر (Fire Blanket) بدە بەسەریدا و لای مەبە.","لە کافتریای فەرمانگەدا: ئاگرکوژێنەرەوەی Wet Chemical لە نزیک شوێنی لێنانی خواردن (NFPA 10: زیاتر لە ٩ مەتر نەبێت).","ستاندارد: BS EN 3-7، NFPA 10، NFPA 17A (Wet Chemical Systems)."]},{heading:"٦. هەڵبژاردنی ئاگرکوژێنەرەوەی گونجاو — خشتەی بڕیاردان",body:"بنەما: ١) ئەو مادەیەی دەسووتێت، ٢) قەبارەی ئاگرەکە، ٣) شوێن:",points:["خشتە: A: ئاو یان ABC | B شلە: کەف، CO₂ یان ABC (شلە جەمسەرییەکان: کەفی AR، CO₂ یان ABC) | B گاز: ئەگەر سەلامەت بوو سەرەتا گازەکە ڕابگرە؛ هەرگیز ئاگری گازێک مەکوژێنەرەوە کە ناتوانیت گازەکەی ڕابگریت | C: CO₂، Clean Agent یان تۆزی ABC (تۆز زیان بە ئامێرە ئەلیکترۆنییەکان دەگەیەنێت) | D: ئاگرکوژێنەرەوەی D کە ناوی ئەو کانزایەی لەسەرە | F/K: Wet Chemical.","قەبارە: ئاگرکوژێنەرەوە تەنها بۆ ئاگرێکی بچووک کە تازە دەستی پێکردووە بەکاربهێنە؛ بەکاری مەهێنە ئەگەر ئاگرەکە لە سەتڵێکی خاشاک گەورەتر بوو، بڵاو دەبێتەوە یان دووکەڵ زیاد دەبێت: دەربچۆ و پەیوەندی بە ١١٥ەوە بکە.","شوێن: ژوورەکانی ICT: Clean Agent یان CO₂ | کۆگاکانی کاغەز: ئاو یان ABC | کافتریا: Wet Chemical.","بۆ فەرمانگەیەکی ئاسایی: ABC و CO₂، و Wet Chemical لە چێشتخانەدا.","ماوەی کارکردن: ئاگرکوژێنەرەوە بچووکەکان بە خێرایی بەتاڵ دەبن، زۆر جار لە چەند چرکەیەکدا؛ کاتی دروستی بەتاڵبوون لەسەر لەیبڵەکە نووسراوە — پێش دەستپێکردن لە ناو ئەو مەودایەدا بە کە لەسەر لەیبڵەکە هاتووە، و ڕێگای دەرچوون لە پشتتەوە بێت.","پشکنین و خزمەتگوزاری (NFPA 10 و OSHA؛ یاساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە): پشکنینی بینراو مانگانە؛ پشکنین و چاکردنەوە ساڵانە لەلایەن تەکنیکارێکی شارەزاوە؛ پڕکردنەوە دوای هەر بەکارهێنانێک؛ تۆزی وشکی پەستاندار: هەر ٦ ساڵ جارێک بەتاڵکردنەوە و پشکنینی ناوەکی؛ تاقیکردنەوەی پەستان (Hydrostatic): هەر ٥ ساڵ جارێک بۆ ئاو، کەف، CO₂، Wet Chemical و تۆزی وشک کە لاشەکەی پۆڵای ژەنگنەگرە (Stainless Steel)، هەر ١٢ ساڵ جارێک بۆ تۆزی وشکی پەستاندار کە لاشەکەی لە ئاسنی نەرم، مسی زەردی لەحیمکراو یان ئەلەمنیۆمە."]},{heading:"٧. قۆناغەکانی گەشەکردنی ئاگر (Stages of Fire)",body:"هەر ئاگرێک بە ٤ قۆناغدا تێدەپەڕێت:",points:["١. سەرەتا (Incipient): دووکەڵی کەم و ئاگری بچووک.","٢. گەشەکردن (Growth): گەرما زیاد دەبێت و ئاگرەکە بڵاو دەبێتەوە.","٣. گەشەکردنی تەواو (Fully Developed): هەموو مادەکانی ژوورەکە دەسووتێن و گەرما دەتوانێت لە ١٠٠٠°C تێپەڕێت.","٤. دابەزین (Decay): سووتەمەنی کەم دەبێتەوە، بەڵام مەترسیی Backdraft هەیە.","Flashover لە نێوان قۆناغەکانی ٢ و ٣ دا: کاتێک گەرمیی چینی سەرەوەی گازەکان دەگاتە نزیکەی ٥٠٠-٦٠٠°C، هەموو مادەکانی ژوورەکە بە خێرایی ئاگر دەگرن.","Backdraft: کردنەوەی دەرگای ژوورێک کە ئاگری تێدایە و ئۆکسجینی کەمە، ئۆکسجینی پێدەگەیەنێت و تەقینەوەیەکی ئاگرین ڕوودەدات.","وەڵامی فەرمانبەر: تەنها لە قۆناغی ١ (Incipient) دا کوژاندنەوەی ئاگر سەلامەتە."]}],media:[{kind:"video",src:"media/videos/gov_fire_classes.mp4",title:"پۆلێنکردنی جۆرەکانی ئاگر",description:"نیشاندانی پۆلەکانی ئاگر بەپێی NFPA و EN 2"},{kind:"image",src:"media/images/gov_fire_decision.png",title:"خشتەی بڕیاردان (Decision Matrix)",description:"هەڵبژاردنی ئاگرکوژێنەرەوەی گونجاو"}],quiz:[{question:"ئاگری کۆمپیوتەر (پۆلی C لە NFPA) بە کام ئاگرکوژێنەرەوە دەکوژێنرێتەوە؟",options:[{text:"ئاو",correct:!1},{text:"CO₂ یان Clean Agent",correct:!0},{text:"کەف",correct:!1},{text:"ئاگرکوژێنەرەوەی D",correct:!1}],explanation:"CO₂ یان Clean Agent — هیچ پاشماوەیەک بەجێ ناهێڵن. تۆزی ABC یش کار دەکات بەڵام زیان بە ئامێرە ئەلیکترۆنییەکان دەگەیەنێت. ئاو و کەفی ئاسایی کارەبا دەگوازنەوە و دەتوانن شۆک دروست بکەن."},{question:"پۆلی D چییە؟",options:[{text:"شلە",correct:!1},{text:"دار و کاغەز",correct:!1},{text:"کانزا سووتەمەنییەکان",correct:!0},{text:"گاز",correct:!1}],explanation:"پۆلی D = کانزا سووتەمەنییەکان (مەگنیسیۆم، تیتانیۆم...). تەنها ئاگرکوژێنەرەوە یان مادەیەک کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت؛ لمی وشک تەنها ئەگەر پلانی ئاگری شوێنەکە یان SDS ی کانزاکە ناوی هێنابێت و تەواو وشک بێت."},{question:"بۆچی نابێت ئاو بەسەر ئاگری ڕۆنی چێشتلێناندا بکرێت؟",options:[{text:"کار ناکات",correct:!1},{text:"ئاو دەبێتە هەڵم و ڕۆنی سووتاو بە هێز دەپژێنێت",correct:!0},{text:"زۆر قورسە",correct:!1},{text:"ڕۆن هەرگیز ئاگر ناگرێت",correct:!1}],explanation:"ڕۆنی زۆر گەرم ئاو بە خێرایی دەکاتە هەڵم؛ هەڵمەکە ڕۆنی سووتاو دەپژێنێت و تۆپەڵە ئاگرێک دروست دەکات."},{question:"NFPA 10 ستانداردی چییە؟",options:[{text:"پۆلێنکردنی کارمەندان",correct:!1},{text:"ئاگرکوژێنەرەوەی دەستی (Portable Fire Extinguishers)",correct:!0},{text:"سیستەمەکانی پرژاندنی ئاو (Sprinkler)",correct:!1},{text:"پاراستنی داتا",correct:!1}],explanation:"NFPA 10 ستانداردی ئەمریکییە بۆ ئاگرکوژێنەرەوەی دەستی: هەڵبژاردن، دانان، پشکنین و چاکردنەوە."},{question:"کام قۆناغی ئاگر تاکە قۆناغە کە فەرمانبەر بتوانێت بە سەلامەتی ئاگرەکە بکوژێنێتەوە؟",options:[{text:"دابەزین (Decay)",correct:!1},{text:"گەشەکردنی تەواو (Fully Developed)",correct:!1},{text:"سەرەتا (Incipient)",correct:!0},{text:"گڕگرتنی گشتیی لەناکاو (Flashover)",correct:!1}],explanation:"تەنها لە قۆناغی سەرەتادا (Incipient) کوژاندنەوەی ئاگر لەلایەن فەرمانبەرەوە سەلامەتە."},{question:"Flashover بە گشتی کاتێک ڕوودەدات کە گەرمیی چینی سەرەوەی گازەکان دەگاتە نزیکەی چ پلەیەک؟",options:[{text:"٢٠٠°C",correct:!1},{text:"٤٠٠°C",correct:!1},{text:"نزیکەی ٥٠٠-٦٠٠°C",correct:!0},{text:"٩٠٠°C",correct:!1}],explanation:"Flashover کاتێک ڕوودەدات کە گەرمیی چینی سەرەوەی گازەکان دەگاتە نزیکەی ٥٠٠-٦٠٠°C — هەموو مادەکانی ژوورەکە بە خێرایی ئاگر دەگرن."}]},{id:18,code:"GOV-118",icon:"FireExtinguisher",accent:"#ea580c",title:"ئاگرکوژێنەرەوەکان — جۆر و هەڵبژاردن",subtitle:"Fire Extinguisher Types — NFPA 10 + BS EN 3",summary:"شەش جۆرە سەرەکییەکەی ئاگرکوژێنەرەوەی دەستی بەپێی ستانداردە نێودەوڵەتییەکان و هەڵبژاردنیان بۆ فەرمانگەکان",blocks:[{body:"ئاگرکوژێنەرەوە لە فەرمانگەکاندا دەبێت بەپێی جۆری ئەو ئاگرەی ئەگەری ڕوودانی هەیە هەڵبژێردرێت. بۆ زۆربەی فەرمانگەکان، تۆزی ABC و CO₂ پێکەوە بنەمان، و Wet Chemical لە چێشتخانەدا. ئەم وانەیە شەش جۆرە سەرەکییەکە، ڕەنگەکانیان، قەبارە، ڕێکاری PASS و خشتەی پشکنین ڕوون دەکاتەوە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. ڕەنگ پۆلی ئاگر نییە: ئەو ڕەنگانەی خوارەوە ڕێکاری بەریتانیان (لاشەی سوور بەپێی BS EN 3 و پارچەیەکی ڕەنگکراو بەپێی BS 7863)؛ ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ (Label) و نیشانەکانی پۆل بخوێنەرەوە."},{heading:"١. ئاگرکوژێنەرەوەی ئاو — Water (پۆلی A)",body:"باوترین ئاگرکوژێنەرەوە بۆ پۆلی A — مادە ڕەقەکان:",points:["ڕەنگ لە بەریتانیا (BS EN 3): هەمووی سوور، بێ پارچە.","پۆل: تەنها A (دار، کاغەز، قوماش، پلاستیک).","چۆنیەتیی کارکردن: ئاگرەکە سارد دەکاتەوە و گەرما کەم دەکاتەوە.","قەبارە باوەکان: ٦ و ٩ لیتر.","دووری: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","هەرگیز بۆ کارەبا (شۆک)، شلەکان و ڕۆنی چێشتلێنان (ئاگرەکە بڵاو دەکاتەوە) بەکاری مەهێنە.","لە فەرمانگەدا: ڕاڕەو و ژوورەکانی ئەرشیف.","نرخەکەی کەمە، بەڵام تەنها بۆ پۆلی A گونجاوە.","پشکنین: پشکنینی بینراوی مانگانە (پێوەری پەستان ئەگەر هەبێت، سنجاقی سەلامەتی و مۆر) و پشکنین و چاکردنەوەی ساڵانە لەلایەن کەسێکی شارەزاوە."]},{heading:"٢. ئاگرکوژێنەرەوەی کەف — Foam (پۆلەکانی A و B)",body:"کەفی AFFF (Aqueous Film-Forming Foam):",points:["ڕەنگ لە بەریتانیا (BS EN 3 / BS 7863): سوور بە پارچەیەکی کرێمی.","پۆل: A و B (شلە سووتەمەنییەکان) — نەک بۆ ئەلکهول و شلە جەمسەرییەکانی تر (Polar Solvents) مەگەر کەفی بەرگەگری ئەلکهول (AR Foam) بێت، و هەڵبژاردەی گشتی نییە بۆ ئاگری گاز.","چۆنیەتیی کارکردن: کەفەکە چینێک لەسەر شلەکە دروست دەکات، ئۆکسجین دەبڕێت و سارد دەکاتەوە.","قەبارە باوەکان: ٦ و ٩ لیتر.","دووری: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵەکە هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","گونجاو بۆ: کۆگاکانی سووتەمەنی و شوێنی موەلیدەکان.","بۆ ئامێرە کارەباییە کارەبادارەکان بەکاری مەهێنە — وەک ئاو کارەبا دەگوازێتەوە.","لە فەرمانگەدا: پارکینگی ئۆتۆمبێل و کۆگای گازۆیل.","AFFF مادەی PFAS ی تێدایە کە زیان بە ژینگە و تەندروستی دەگەیەنن؛ کەفی بێ فلۆر (Fluorine-Free Foam) جێگرەوە نوێیەکەیە."]},{heading:"٣. ئاگرکوژێنەرەوەی CO₂ — Carbon Dioxide (پۆلی B و ئاگری کارەبایی)",body:"باشترین بۆ ئامێرە کارەباییەکان و شلەکان:",points:["ڕەنگ لە بەریتانیا (BS EN 3 / BS 7863): سوور بە پارچەیەکی ڕەش.","پۆل: B و ئامێرە کارەباییە کارەبادارەکان (پۆلەکانی B و C لە NFPA؛ لە EN 2 دا پۆلی C گازە و CO₂ بۆ ئاگری گاز پەسەند نەکراوە).","چۆنیەتیی کارکردن: گازی CO₂ ئۆکسجین لە دەوری ئاگرەکە لادەبات (خنکاندن).","قەبارە باوەکان: ٢ و ٥ کگ.","دووری: مەودای CO₂ کورتە؛ لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵەکە هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","گونجاو بۆ: ژوورەکانی ICT، تابلۆکانی کارەبا، ژووری سێرڤەرەکان (Server Room).","هیچ پاشماوەیەک بەجێ ناهێڵێت و زیان بە ئامێرە گرانبەهاکان ناگەیەنێت؛ بەڵام بۆ ئاگری قووڵی پۆلی A باش نییە.","مەترسی: لە ژووری داخراودا ئۆکسجین کەم دەکاتەوە — دوای بەکارهێنان ژوورەکە چۆڵ بکە و هەواکەی نوێ بکەرەوە.","قیفەکەی زۆر سارد دەبێت (نزیکەی −٧٨°C) — دەست لە قیفەکە مەدە، تەنها دەسکەکە بگرە.","لە فەرمانگەدا: بەشی ICT، ژووری سێرڤەرەکان و لە نزیک تابلۆکانی کارەبا."]},{heading:"٤. ئاگرکوژێنەرەوەی تۆزی وشکی ABC — Dry Chemical Powder",body:"باوترین ئاگرکوژێنەرەوە — بۆ پۆلەکانی A، B و C، نەک بۆ D و K/F:",points:["ڕەنگ لە بەریتانیا (BS EN 3 / BS 7863): سوور بە پارچەیەکی شین.","پۆل: A، B و C — نەک D (کانزا) و نەک K/F (ڕۆنی چێشتلێنان).","مادە: فۆسفاتی ئەمۆنیۆم (Monoammonium Phosphate).","چۆنیەتیی کارکردن: تۆزەکە کارلێکی کیمیاییی ئاگرەکە ڕادەگرێت.","قەبارە باوەکان: ١، ٢، ٦ و ٩ کگ.","دووری: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵەکە هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","گونجاو بۆ: ڕاڕەو، گەراج و کۆگا — نەک بۆ ڕۆنی چێشتلێنان.","تۆزەکە لە ژوورەکەدا بڵاو دەبێتەوە، بینین کەم دەکاتەوە و پاککردنەوەی قورسە.","تۆزەکە زیان بە ئامێرە ئەلیکترۆنییەکان دەگەیەنێت — بۆ کۆمپیوتەر و ICT، CO₂ باشترە.","لە فەرمانگەدا: ڕاڕەو، گەراج و لە نزیک دەرچوونەکان.","نرخەکەی کەمە و بە گشتی لە فەرمانگەکاندا دادەنرێت."]},{heading:"٥. ئاگرکوژێنەرەوەی مادەی تەڕ — Wet Chemical (پۆلی F/K) — چێشتخانە",body:"تایبەتە بە ڕۆن و چەوریی گەرمی چێشتخانە:",points:["ڕەنگ لە بەریتانیا (BS EN 3 / BS 7863): سوور بە پارچەیەکی زەرد.","پۆل: K (NFPA) / F (EN 2) — ڕۆنی چێشتلێنان.","مادە: خوێیەکانی پۆتاسیۆم (Potassium Acetate یان Potassium Citrate).","چۆنیەتیی کارکردن: ڕۆنەکە دەکاتە چینێکی وەک سابوون (Saponification) کە ڕۆنەکە سارد دەکاتەوە و ئۆکسجین دەبڕێت.","قەبارە باوەکان: ٢ و ٦ لیتر.","بەپێی لەیبڵەکە بەکاری بهێنە: بە هێواشی و بە لوولەی درێژ بەسەر ڕۆنەکەدا بیڕێژە بۆ ئەوەی ڕۆنەکە نەپژێت.","بۆ ڕۆن و چەوریی چێشتلێنان دروستکراوە (NFPA K / EN F)؛ زۆرێکیان بۆ پۆلی A یش گونجاون، بۆیە لەیبڵەکە بخوێنەرەوە. نەک بۆ گازۆیل و نەوت (پۆلی B).","هەرگیز ئاو بەسەر ڕۆنی گەرمدا مەکە — ئاو دەبێتە هەڵم و ڕۆنی سووتاو دەپژێنێت!","لە فەرمانگەدا: کافتریا و چێشتخانە.","پێش بەکارهێنان، ئەگەر سەلامەت بوو، گاز یان کارەبای ئامێری لێنانی خواردن ببڕە."]},{heading:"٦. مادە پاکەکان — Clean Agent (FK-5-1-12 / HFC-227ea)",body:"بۆ ICT و ئامێرە گرانبەهاکان:",points:["ڕەنگ: لەشی سوور و ناوی مادەکەی لەسەر نووسراوە (لە هەندێک وڵات نیشانەیەکی سەوز).","پۆل: بەپێی مۆدێل دەگۆڕێت؛ لەیبڵەکە بخوێنەرەوە.","مادە: FK-5-1-12 (ناوی بازرگانی Novec 1230) یان HFC-227ea.","چۆنیەتیی کارکردن: گازێکی پاکە — هیچ پاشماوەیەک بەجێ ناهێڵێت و زیان بە ئامێرەکان ناگەیەنێت.","سیستەمە جێگیرەکانی مادەی پاک (NFPA 2001)، کە ئاگرکوژێنەرەوەی دەستی نین، لە ١٠ چرکە یان کەمتردا بەتاڵ دەبنەوە.","گونجاو بۆ: ژووری سێرڤەرەکان (Server Room)، ناوەندی داتا (Data Center)، ئەرشیف.","ئاگرکوژێنەرەوەی دەستیی مادەی پاک: پۆل و کەمترین قەبارەی ژوور لەسەر لەیبڵەکەن؛ دوای بەکارهێنان ژوورەکە جێ بهێڵە. سیستەمە جێگیرەکان: بە ڕێژەکانی دیزاین مادەکە بۆ مرۆڤ سەلامەتە، بەڵام بەهۆی دووکەڵ و ئەو مادانەی لە ئاگرەکەوە دروست دەبن، دەبێت ژوورەکە چۆڵ بکرێت.","زیان بە چینی ئۆزۆن ناگەیەنێت و جێگەی Halon 1301 ی گرتووەتەوە.","گرانە؛ لە ژووری سێرڤەرەکاندا زۆر جار وەک سیستەمێکی جێگیری پڕکردنەوەی ژوور (Total Flooding) دادەنرێت، کە جیاوازە لە ئاگرکوژێنەرەوەی دەستی.","لە فەرمانگەدا: تەنها لە شوێنە هەستیارەکان — ژووری سێرڤەرەکان و ناوەندی کارەکانی تەنگانە (EOC).","ستاندارد: NFPA 2001 (Clean Agent Fire Extinguishing Systems)."]},{heading:"٧. PASS — ڕێکاری بەکارهێنان",body:`پێش بەکارهێنانی ئاگرکوژێنەرەوە (دەبێت هەموو وەڵامەکان «بەڵێ» بن):
• ئاگرەکە بچووکە و تازە دەستی پێکردووە، وەک ئاگرێک لە سەتڵی خاشاک یان تاوەیەکدا.
• ئاگرکوژێنەرەوەکە گونجاوە بۆ ئەم جۆرە ئاگرە.
• ڕێگای دەرچوون لە پشتتەوەیە و ئاگرەکە لە نێوان تۆ و دەرچوونەکەدا نییە.
• ئاگادارکردنەوە دراوە: ئەوانی تر ئاگادار کراونەتەوە و پەیوەندی بە ١١٥ەوە کراوە.
• تۆ بۆ بەکارهێنانی ئاگرکوژێنەرەوە ڕاهێنراویت.
• هیچ دووکەڵ یان گەرمایەک ڕێگای دەرچوونت ناگرێت.
• ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، بوەستە، دەربچۆ و دەرگاکە لە دوای خۆتەوە دابخە.

ڕێکاری PASS ڕێگای گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان. ئاگرکوژێنەرەوەکانی Class D، مادەی تەڕ (Wet Chemical)، مادەی پاک (Clean Agent) و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە. هەنگاو بە هەنگاو:`,points:["P = Pull (ڕایبکێشە): سنجاقی سەلامەتی ڕابکێشە و مۆرەکە بشکێنە.","A = Aim (ئاراستەی بکە): سەری لوولەکە بەرەو بنی ئاگرەکە، نەک سەری ئاگرەکە — لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","S = Squeeze (بیگووشە): دەسکەکە بە هێز و بە بەردەوامی بگووشە.","S = Sweep (بیجووڵێنە): لە لایەکەوە بۆ لایەکی تر، بە هێواشی، تا ئاگرەکە دەکوژێتەوە.","ئاگرکوژێنەرەوە بچووکەکان بە خێرایی بەتاڵ دەبن، زۆر جار لە چەند چرکەیەکدا؛ کاتی دروستی بەتاڵبوون لەسەر لەیبڵەکە نووسراوە — ئامادە بە.","شوێنی وەستان: ڕێگای دەرچوون (دەرگا) لە پشتتەوە بێت.","دوای کوژاندنەوە چاودێریی شوێنەکە بکە؛ ئەگەر ئاگرەکە دیسان هەڵگیرسایەوە، دووبارە PASS ئەنجام بدە یان دەربچۆ.","ئەگەر ئاگرەکە یەکسەر نەکوژایەوە یان ئاگرکوژێنەرەوەکە بەتاڵ بوو: یەکسەر دەربچۆ، دەرگاکە لە دوای خۆتەوە دابخە و دڵنیا ببەوە کە پەیوەندی بە ١١٥ەوە کراوە."]},{heading:"٨. هەڵبژاردنی گونجاو بۆ فەرمانگەکان",body:"پلانی ئاگرکوژێنەرەوەکانی فەرمانگە:",points:["نموونە بۆ فەرمانگەیەک: ABC لە ڕاڕەوەکان، CO₂ لە نزیک ئامێرە کارەباییەکان و ICT، و Wet Chemical لە چێشتخانە (ئەگەر هەبێت).","بەپێی NFPA 10، لە شوێنێکی مەترسیی کەم (Light Hazard) هەر یەکەیەکی A (A Unit) ڕووبەرێک تا ٣٠٠٠ پێ² (نزیکەی ٢٧٩ م²) دەپارێزێت، بۆیە ئاگرکوژێنەرەوەیەکی 2-A تا نزیکەی ٥٥٧ م² (٦٠٠٠ پێ²) دەپارێزێت؛ هیچ ئاگرکوژێنەرەوەیەک نابێت لە نزیکەی ١٠٤٥ م² (١١٢٥٠ پێ²) زیاتر بپارێزێت، و نابێت هیچ کەسێک پێویستی بە ڕۆیشتنی زیاتر لە ٢٣ مەتر (٧٥ پێ) بێت بۆ گەیشتن بە ئاگرکوژێنەرەوەیەک. کۆدی بەریتانی BS 5306-8 پێشنیار دەکات کە لانیکەم ٢ ئاگرکوژێنەرەوە لە هەر نهۆمێکدا هەبێت (جگە لە نهۆمە زۆر بچووکەکان). پێداویستیی فەرمانگەکانی دهۆک لەلایەن بەڕێوەبەرایەتیی بەرگریی شارستانییەوە دادەنرێت و هێشتا پشتڕاست نەکراوەتەوە.","دووریی گەیشتن (Travel Distance): زیاتر لە ٢٣ مەتر نەبێت بۆ پۆلی A، ٩ یان ١٥ مەتر بۆ پۆلی B (بەپێی پلەی ئاگرکوژێنەرەوەکە)، ٩ مەتر بۆ پۆلی K (NFPA 10).","لەسەر دیوار و لە نزیک دەرگاکان؛ سەری ئاگرکوژێنەرەوەکە بەرزتر نەبێت لە ١٫٥ مەتر لە زەوییەوە (بۆ ئاگرکوژێنەرەوەکانی تا ١٨ کگ — NFPA 10).","نیشانەی ئاگرکوژێنەرەوە (ISO 7010 F001) لە شوێنێکی بەرز دابنێ بۆ ئەوەی لە دوورەوە ببینرێت.","پشکنینی بینراو (مانگانە، لەلایەن کارمەندێکی دیاریکراوەوە): لە شوێنی خۆیدا بێت، دیار بێت و بە ئاسانی دەستی پێ بگات؛ سنجاقی سەلامەتی و مۆرەکە نەشکابن؛ لەیبڵەکە بخوێنرێتەوە و ڕووی لە دەرەوە بێت؛ هیچ زیان، ژەنگ یان دزەکردنێکی نەبێت؛ لوولە و سەری لوولەکە نەگیرابن؛ ئەگەر پێوەری پەستانی هەبوو، دەرزییەکەی لە ناوچە سەوزەکەدا بێت. ئاگرکوژێنەرەوەی CO₂ پێوەری نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.","پشکنین و چاکردنەوە (ساڵانە، لەلایەن تەکنیکارێکی شارەزا لە کۆمپانیایەکی پەسەندکراوەوە).","پڕکردنەوە (Recharge): دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت، لەلایەن تەکنیکارێکی شارەزاوە.","چاکردنەوەی ٦ ساڵە: ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستاندار (ABC، Stored Pressure) کە پێویستیان بە تاقیکردنەوەی پەستانی ١٢ ساڵە هەیە، هەر ٦ ساڵ جارێک بەتاڵ دەکرێنەوە و پشکنینی ناوەکییان بۆ دەکرێت (NFPA 10) — ئەمە گۆڕینی ئاگرکوژێنەرەوەکە نییە.","تاقیکردنەوەی پەستانی لاشەی ئاگرکوژێنەرەوەکە (Hydrostatic Test)، بەپێی جۆر: هەر ٥ ساڵ جارێک بۆ ئاو، کەف (AFFF)، CO₂، Wet Chemical و ئاگرکوژێنەرەوەی تۆزی وشک کە لاشەکەی پۆڵای ژەنگنەگرە (Stainless Steel)؛ هەر ١٢ ساڵ جارێک بۆ ئاگرکوژێنەرەوەی تۆزی وشکی پەستاندار (ABC) کە لاشەکەی لە ئاسنی نەرم (Mild Steel)، مسی زەردی لەحیمکراو (Brazed Brass) یان ئەلەمنیۆمە. یاساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە.","لابردن لە خزمەت: ئاگرکوژێنەرەوە لە خزمەت لادەبرێت ئەگەر لە پشکنین یان تاقیکردنەوەدا سەرنەکەوێت، زیانی پێ گەیشتبێت، کۆن بووبێت (Obsolete) یان لەلایەن کۆمپانیاکەوە گەڕێندرابێتەوە (Recall)، لەیبڵەکەی نەخوێنرێتەوە، یان ئاگرکوژێنەرەوەیەکی یەکجاری (Non-rechargeable) بێت و ماوەی کارکردنی سەر لەیبڵەکەی تێپەڕیبێت."]}],media:[{kind:"video",src:"media/videos/gov_ext_pass.mp4",title:"ڕێکاری PASS (PASS Technique)",description:"تاقیکردنەوەی ڕێکاری PASS"},{kind:"image",src:"media/images/gov_ext_chart.png",title:"خشتەی هەڵبژاردنی ئاگرکوژێنەرەوەکان (Extinguisher Selection Chart)",description:"هەڵبژاردن بەپێی پۆلی ئاگر"}],quiz:[{question:"ئاگرکوژێنەرەوەی ABC بۆ کام پۆلانە گونجاوە؟",options:[{text:"تەنها A",correct:!1},{text:"A + B + C",correct:!0},{text:"تەنها B + C",correct:!1},{text:"D + K",correct:!1}],explanation:"ABC بۆ پۆلەکانی A، B و C یە (فۆسفاتی ئەمۆنیۆم) — نەک بۆ D (کانزا) و نەک بۆ K/F (ڕۆنی چێشتلێنان)."},{question:"بۆ ژووری سێرڤەرەکان (Server Room)، کام ئاگرکوژێنەرەوە گونجاوە؟",options:[{text:"تۆزی ABC",correct:!1},{text:"ئاو",correct:!1},{text:"مادە پاکەکان — Clean Agent (FK-5-1-12)",correct:!0},{text:"کەف",correct:!1}],explanation:"Clean Agent هیچ پاشماوەیەک بەجێ ناهێڵێت و زیان بە ئامێرەکان ناگەیەنێت."},{question:"P لە PASS دا مانای چییە؟",options:[{text:"Push",correct:!1},{text:"Pull",correct:!0},{text:"Point",correct:!1},{text:"Press",correct:!1}],explanation:"P = Pull (سنجاقی سەلامەتی ڕابکێشە)."},{question:"بەپێی NFPA 10، دووریی گەیشتن (Travel Distance) بۆ ئاگرکوژێنەرەوەی پۆلی A نابێت لە چەند زیاتر بێت؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٣ مەتر",correct:!0},{text:"٥٠ مەتر",correct:!1},{text:"١٠٠ مەتر",correct:!1}],explanation:"NFPA 10: تا ٢٣ مەتر (٧٥ پێ) بۆ پۆلی A؛ بۆ پۆلی B ٩ یان ١٥ مەتر بەپێی پلەی ئاگرکوژێنەرەوەکە."},{question:"پلەی گەرمیی CO₂ لە کاتی دەرچوون لە ئاگرکوژێنەرەوەکەدا نزیکەی چەندە؟",options:[{text:"٠°C",correct:!1},{text:"−٧٨°C",correct:!0},{text:"−٣٠°C",correct:!1},{text:"٢٠°C",correct:!1}],explanation:"CO₂ بە پلەی گەرمیی نزیکەی −٧٨°C دەردەچێت — دەست لە قیفەکە مەدە، بۆ ئەوەی دەستت بەهۆی سەرماوە نەسووتێت (Frostbite)."},{question:"مەترسیی کەفی AFFF چییە؟",options:[{text:"هیچ مەترسییەکی نییە",correct:!1},{text:"PFAS — زیانی ژینگەیی",correct:!0},{text:"زۆر گرانە",correct:!1},{text:"زۆر ساردە",correct:!1}],explanation:"AFFF مادەی فلۆریی (PFAS) تێدایە کە مەترسی بۆ سەر ژینگە دروست دەکەن؛ کەفی بێ فلۆر جێگرەوە نوێیەکەیە."}]},{id:19,code:"GOV-119",icon:"HeartHandshake",accent:"#db2777",title:"فریاکەوتنی سەرەتایی بۆ فەرمانبەران",subtitle:"Workplace First Aid — Primary Check + CPR + AED + Common Emergencies",summary:"بەرنامەی تەواوی فریاکەوتنی سەرەتایی بۆ کارمەندانی فەرمانگەکان",blocks:[{body:"لە تەنگانەدا، یەکەم خولەکەکان زۆر گرنگن: ئەگەر دڵ وەستا، زیانی مێشک دوای چەند خولەکێک دەست پێدەکات، و هەر خولەکێک دواکەوتنی CPR و شۆکی AED دەرفەتی ڕزگاربوون کەم دەکاتەوە. ئەم وانەیە پشکنینی سەرەتایی، CPR لە فەرمانگەدا، AED، خنکان، خوێنبەربوون، سووتان و تەنگانە باوەکانی تر ڕوون دەکاتەوە."},{heading:"١. پشکنینی سەرەتایی — مەترسی، وەڵامدانەوە، هەناسە",body:"یەکەم ڕێکار دوای بینینی کەسێکی کەوتوو یان بێهێز:",points:["مەترسی (Danger): پێش ئەوەی نزیک ببیتەوە، شوێنەکە بپشکنە: کارەبا، ئاگر، گاز، هاتوچۆ؟ سەلامەتیی خۆت لە پێشەوەیە.","وەڵامدانەوە (Response): بە هێواشی شانەکانی ڕابوەشێنە و بە دەنگی بەرز بپرسە: «باشیت؟»","ئەگەر وەڵامی نەدایەوە: داوای یارمەتی بکە، پەیوەندی بە ١٢٢ بکە (مۆبایلەکە بخەرە سەر سپیکەر) و کەسێک بنێرە بۆ ئەوەی AED بهێنێت.","هەناسە (Breathing): تا ١٠ چرکە سەیری سنگی بکە بزانە بە دروستی بەرز و نزم دەبێتەوە یان نا.","ئەگەر هەناسەی نەدا یان تەنها هەناسەی نائاسایی (Gasping) هەبوو: ئەمە وەستانی دڵە — یەکسەر فشاری سنگ دەست پێ بکە.","کەسانی ئاسایی (نا پزیشک) لێدانی دڵ (Pulse) ناپشکنن — کات بە پشکنین بە فیڕۆ مەدە.","ئەگەر بە دروستی هەناسەی دەدا و گومانی برینداربوونی مل یان پشت نەبوو: لەسەر لای دایبنێ (Recovery Position)، هیچی بە دەمدا مەدەرێ و چاودێریی هەناسەی بکە تا ئەمبولانس دەگات."]},{heading:"٢. CPR لە فەرمانگەدا",body:"بۆ کارمەندان (نا پزیشک):",points:["شوێنی دەستەکان: ناوەڕاستی سنگ (نیوەی خوارەوەی ئێسکی سنگ)، دەستێک لەسەر ئەوی تر.","باسکەکان ڕاست بن و شانەکانت ڕاستەوخۆ لەسەر سنگەکە بن؛ هێز لە کەمەر و لەشتەوە بدە.","قووڵی: ٥-٦ سم بۆ هەموو گەورەساڵان.","خێرایی: ١٠٠-١٢٠ فشار لە خولەکێکدا؛ دوای هەر فشارێک با سنگەکە بە تەواوی بگەڕێتەوە.","ڕێژە: ٣٠ فشار + ٢ هەناسە؛ ئەگەر ڕاهێنانت نەبینیوە، تەنها فشاری سنگ (Hands-Only CPR) بکە.","ئەگەر دوو کەس هەبوون: هەر ٢ خولەک جارێک (٥ خول) جێگۆڕکێ بکەن بۆ ئەوەی هێزی فشارەکان کەم نەبێتەوە.","مەوەستە تا: AED دەگات و کار دەکات، تیمی پزیشکی دەگات، یان کەسەکە بە ئاشکرا بەئاگا دێتەوە.","هەڵە باوەکان: قووڵیی کەم، خێراییی کەم، وەستانی درێژ، و ڕێگەنەدان بە سنگ بۆ گەڕانەوە."]},{heading:"٣. AED — ئامێری شۆکی دڵی ئۆتۆماتیکی (Automated External Defibrillator)",body:"پێشنیار دەکرێت لە هەر بینایەکی حکومیی گەورەدا هەبێت:",points:["شوێن: لە ڕاڕەوێکی گشتی و دیاردا، بۆ ئەوەی بە خێرایی پێی بگەن.","نیشانە: سندووق بە نیشانەی AED (ISO 7010 E010) و بە ڕووناکییەکی دیار.","ئامانج: AED لە ماوەی نزیکەی ٣ خولەکدا بگاتە هەر شوێنێکی بیناکە.","هەنگاوەکان: ١) هەڵیبکە، ٢) دوو پەدەکە لەسەر سنگی ڕووت دابنێ، ٣) گوێ لە دەنگەکە بگرە، ٤) ئەگەر داوای شۆکی کرد، دوگمەکە دابگرە.","پێش شۆک بە دەنگی بەرز بڵێ «دوور بکەونەوە!» — با کەس دەست لە کەسەکە نەدات.","پشکنینی مانگانە: پاتری و بەرواری بەسەرچوونی پەدەکان.","دوای شۆک: یەکسەر ٢ خولەک CPR بکە، دواتر AED دووبارە شیکاری دەکات.","دوای بەکارهێنان: پەد و پاتریی نوێ دابنێ بۆ ئەوەی ئامێرەکە بۆ جاری داهاتوو ئامادە بێت."]},{heading:"٤. خنکان (Choking)",body:"ئەگەر شتێک لە گەرووی مرۆڤ گیری خوارد:",points:["پشکنین: ئایا دەتوانێت قسە بکات، بکۆکێت یان هەناسە بدات؟","ئەگەر بە هێز دەکۆکێت: هانی بدە بکۆکێت و لە لای بمێنەرەوە.","ئەگەر ناتوانێت قسە بکات، بکۆکێت یان هەناسە بدات: پەیوەندی بە ١٢٢ بکە (یان کەسێکی تر ڕاسپێرە پەیوەندی بکات) و یەکسەر دەست پێ بکە.","٥ لێدانی پشت: بەرەو پێشەوە بیچەمێنەوە و بە بنی دەست بە هێز لە نێوان هەردوو شانیدا لێبدە.","٥ فشاری سک (Heimlich): لە پشتییەوە بوەستە، مستت لە سەرووی ناوک و زۆر لە خوار ئێسکی سنگەوە دابنێ، بە دەستەکەی تر بیگرە و بە خێرایی بەرەو ژوورەوە و سەرەوە فشار بدە.","٥ لێدانی پشت و ٥ فشاری سک دووبارە بکەرەوە تا شتەکە دەردەچێت؛ ئەگەر بێهۆش بوو، CPR دەست پێ بکە.","منداڵی تەمەن کەمتر لە ١ ساڵ: ٥ لێدانی پشت (سەری لە سنگی نزمتر) + ٥ فشاری سنگ بە بنی یەک دەست؛ هەرگیز فشاری سک نا.","ئافرەتی دووگیان یان کەسێک کە دەستەکانت ناگەنە دەوری سکی: فشاری سنگ (Chest thrusts) لە جیاتی فشاری سک."]},{heading:"٥. ڕاگرتنی خوێنبەربوون (Stop the Bleed)",body:"سێ ڕێکارە سەرەکییەکەی Stop the Bleed:",points:["١. فشاری ڕاستەوخۆ: پارچەیەکی پاک لەسەر برینەکە دابنێ و بە هەردوو دەست بە هێز و بەبێ وەستان فشار بدە.","٢. پڕکردنەوەی برین (Wound Packing): لە برینە قووڵەکاندا (ڕان، بنباڵ، مل)، پەڕۆی پاکی برینپێچ بخە ناو برینەکە و بە هێز فشار بدە.","٣. تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونی مەترسیدار لە دەست یان قاچ، بە زوویی؛ ٥-٧ سم لە سەرووی برینەکەوە، نەک لەسەر جومگە.","کاتی دانانی تۆرنیکێت بنووسە و هەرگیز شلی مەکەرەوە یان مەیکەرەوە — تەنها تیمی پزیشکی لای دەبات.","هەرگیز شتی چەقیو لە برین دەرمەهێنە (خوێنبەربوونەکە زیاتر دەبێت).","ئەگەر شتێک چەقیبوو: قوماش لە دەوری بپێچە بۆ ئەوەی نەجووڵێت و فشار لە دەوریدا بدە، نەک لەسەری.","برینی سەر: فشاری هێواش بدە؛ ئەگەر گومانی شکانی ئێسکی سەر هەبوو، فشاری بەهێز مەدە.","برینی چاو: فشار لەسەر چاو مەدە — تەنها بە قوماشێکی پاک بە شلی دایبپۆشە.","لە خوێنبەربوونی سەختدا یەکسەر پەیوەندی بە ١٢٢ بکە؛ ئەگەر قوماشەکە بە خوێن تەڕ بوو، لای مەبە — یەکێکی تر لەسەری دابنێ."]},{heading:"٦. سووتان (Burns)",body:"پلەکانی سووتان و ڕووبەری سووتاوی لەش (TBSA):",points:["پلەی ١ (ڕووکەشی): تەنها سووربوونەوە و ئازار — وەک سووتانی خۆر.","پلەی ٢ (نیمچە قووڵ): بڵق و ئازاری بەهێز.","پلەی ٣ (قووڵ): پێست سپی، قاوەیی یان ڕەش دەبێت؛ لەوانەیە ئازار نەبێت چونکە دەمارەکان سووتاون.","ڕێسای ٩ەکان (Rule of 9s) بۆ گەورەساڵان: سەر ٩٪، هەر باسکێک ٩٪، هەر قاچێک ١٨٪، سنگ و سک ١٨٪، پشت ١٨٪، ئەندامی زاوزێ ١٪.","یەکسەر ٢٠ خولەک بە ئاوی فێنکی ڕەوان سارد بکەرەوە (نەک سەهۆڵ، نەک ئاوی زۆر سارد).","دواتر بە نایلۆنی خواردن (Cling Film) یان قوماشێکی پاکی نەنووساو بە شلی دایبپۆشە.","سووتانی کیمیایی: لانیکەم ٢٠ خولەک بە ئاوی ڕەوان بیشۆ و پەڕەی SDS بپشکنە.","سووتانی کارەبا: یەکەم جار کارەبا ببڕە؛ برینێکی چوونەژوورەوە و برینێکی دەرچوون هەن و لەوانەیە زیانی ناوەکی زیاتر بێت.","هەرگیز: سەهۆڵ، ڕۆن، کرێم یان مەعجوونی ددان؛ بڵقەکان مەتەقێنە و ئەو جلانەی پێوەی نووساون دامەکەنە.","پەیوەندی بە ١٢٢ بکە ئەگەر: سووتانەکە گەورە یان قووڵ بوو، لەسەر دەموچاو، دەست، پێ یان ئەندامی زاوزێ بوو، سووتانی کارەبا بوو، یان کەسەکە دووکەڵی هەڵمژیبوو."]},{heading:"٧. تەنگانە باوەکانی تر",body:"بارودۆخە باوەکان لە فەرمانگەکاندا:",points:["بێهۆشبوونی کورت (Fainting): لەسەر پشت دایبنێ، ئەگەر بریندار نەبوو قاچەکانی نزیکەی ٣٠ سم بەرز بکەرەوە و هەوای تازە بهێنە ژوورەوە.","تەنگانەی شەکرە (Diabetic Emergency): ئەگەر بەئاگا بوو و توانی قووت بدات، شەکر یان خواردنەوەیەکی شیرینی بدەرێ. ئەگەر بێهۆش بوو: هیچی بە دەمدا مەدەرێ، لەسەر لای دایبنێ و پەیوەندی بە ١٢٢ بکە. گلوکاگۆن (Glucagon) تەنها ئەگەر پزیشک بۆی نووسیبێت و تۆ ڕاهێنانت لەسەری بینیبێت.","تۆقینی کتوپڕ (Panic Attack): بە هێمنی لەگەڵی قسە بکە و یارمەتیی بدە بە هێواشی هەناسە بدات؛ هەناسەدان لە ناو کیسەی کاغەزدا ئیتر پێشنیار ناکرێت.","برینی سەر: ئەگەر گومانی برینی بڕبڕەی پشت هەبوو مەیجووڵێنە، مەگەر شوێنەکە مەترسیدار بێت یان پێویستی بە CPR هەبێت (ئەو کاتە سەر، مل و پشت لەسەر یەک هێڵ ڕابگرە)، و لەسەر لا (Recovery Position) دایمەنێ؛ چاودێریی هۆشیاری و هەناسەی بکە و پەیوەندی بە ١٢٢ بکە.","شکان (Fracture): ئەندامەکە وەک خۆی جێگیر بکە (Splint)، ڕاستی مەکەرەوە، سەهۆڵی پێچراو لە قوماشدا بۆ ئازارەکە دابنێ و پەیوەندی بە ١٢٢ بکە.","کارەباگرتن: کارەبا ببڕە، ئەگەر هەناسەی نەدا CPR بکە؛ هەمووان دەبێت لە نەخۆشخانە پشکنینی دڵ (ECG) بکەن.","ژەهراویبوون: ١) کام مادە؟ ٢) چەند؟ ٣) کەی؟ — پەیوەندی بە ١٢٢ بکە، قوتووی مادەکە لەگەڵ خۆت ببە، و هەوڵ مەدە بیڕشێنیتەوە.","پێوەدانی مار (Snake Bite): کەسەکە هێمن و بێجووڵە بهێڵەرەوە و ئەندامەکە بە دار جێگیر بکە؛ هیچ شتێک مەبەستە، مەیبڕە و خوێنەکە مەمژە؛ یەکسەر پەیوەندی بە ١٢٢ بکە."]}],media:[{kind:"video",src:"media/videos/gov_cpr_workplace.mp4",title:"CPR لە فەرمانگەدا (Workplace CPR)",description:"CPR لە شوێنی کار"},{kind:"video",src:"media/videos/gov_aed_demo.mp4",title:"نیشاندانی AED (AED Demo)",description:"بەکارهێنانی AED"}],quiz:[{question:"یەکەم هەنگاو لە پشکنینی سەرەتاییدا چییە؟",options:[{text:"یەکسەر CPR",correct:!1},{text:"پشکنینی مەترسی (Danger)",correct:!0},{text:"پەیوەندی بە ١٢٢ بکە",correct:!1},{text:"AED",correct:!1}],explanation:"پێش هەموو شتێک دڵنیا ببەرەوە کە شوێنەکە بۆ تۆ سەلامەتە — ئەگەر خۆت بریندار ببیت، ناتوانیت یارمەتی بدەیت."},{question:"لە CPR دا، قووڵیی فشارەکان بۆ گەورەساڵان چەندە؟",options:[{text:"٢-٣ سم",correct:!1},{text:"٥-٦ سم",correct:!0},{text:"٨-١٠ سم",correct:!1},{text:"هیچ کامیان",correct:!1,fixed:!0}],explanation:"٥-٦ سم بۆ هەموو گەورەساڵان (AHA 2025)."},{question:"ئەگەر شۆکی AED لە یەکەم ٣-٥ خولەکی دوای کەوتندا بدرێت، دەرفەتی ڕزگاربوون دەتوانێت بگاتە چەند؟",options:[{text:"١٠٪",correct:!1},{text:"تا ٥٠-٧٠٪",correct:!0},{text:"٢٠٪",correct:!1},{text:"١٠٠٪",correct:!1}],explanation:"شۆکی زوو لە ماوەی ٣-٥ خولەکدا دەتوانێت ڕێژەی ڕزگاربوون بگەیەنێتە ٥٠-٧٠٪؛ هەر خولەکێک دواکەوتن دەرفەتەکە بە ڕێژەیەکی بەرچاو کەم دەکاتەوە."},{question:"بۆ منداڵێکی تەمەن کەمتر لە ١ ساڵ کە خنکاوە (و بەئاگایە)، چی دەکرێت؟",options:[{text:"یەکسەر فشاری سک (Heimlich)",correct:!1},{text:"٥ لێدانی پشت + ٥ فشاری سنگ",correct:!0},{text:"تەنها بەجێی بهێڵە",correct:!1},{text:"یەکسەر CPR",correct:!1}],explanation:"٥ لێدانی پشت و ٥ فشاری سنگ بە بنی یەک دەست — هەرگیز فشاری سک بۆ ساوا نا (AHA 2025)."},{question:"دوای دانانی تۆرنیکێت، دەبێت چی بکەیت؟",options:[{text:"هەر ٦ کاتژمێر جارێک شلی بکەرەوە",correct:!1},{text:"کاتی دانانەکەی بنووسە و هەرگیز شلی مەکەرەوە",correct:!0},{text:"دوای ١٠ خولەک لای ببە",correct:!1},{text:"هەر ٢٠ خولەک جارێک شلی بکەرەوە بۆ ئەوەی خوێنی پێبگات",correct:!1}],explanation:"کاتی دانانەکەی بنووسە (Stop the Bleed). تۆرنیکێت لە شوێنی خۆی دەمێنێتەوە تا تیمی پزیشکی لای دەبات؛ شلکردنەوە خوێنبەربوونەکە دەگەڕێنێتەوە."},{question:"سووتان دەبێت ٢٠ خولەک بە چ ئاوێک سارد بکرێتەوە؟",options:[{text:"ئاوی گەرم",correct:!1},{text:"ئاوی فێنکی ڕەوان، نەک سەهۆڵ",correct:!0},{text:"سەهۆڵ",correct:!1},{text:"دەرمان و مەڵهەم",correct:!1}],explanation:"ئاوی فێنکی ڕەوان — نەک ئاوی گەرم (سووتانەکە قووڵتر دەکات) و نەک سەهۆڵ (زیان بە پێست دەگەیەنێت)."}]},{id:20,code:"GOV-120",icon:"Siren",accent:"#2563eb",title:"کاری بەرگریی شارستانی و هەماهەنگی",subtitle:"CD Operations + ICS + Multi-Agency Response",summary:"ڕۆڵی فەرمانگە لە کاتی وەڵامدانەوەی بەرگریی شارستانی (١١٥) و هەماهەنگی لەگەڵ لایەنەکانی تر",blocks:[{body:"فەرمانگەکان دەبێت بزانن چۆن لە کاتی تەنگانەکاندا لەگەڵ بەرگریی شارستانی (١١٥) کار بکەن. ستانداردی NFPA 1660 (کە NFPA 1600 ی تێدا کۆکراوەتەوە) و خولەکانی FEMA ICS-100/200 بنەما نێودەوڵەتییەکانن. بەپێی ICS، یەک فەرماندەی ڕووداو (Incident Commander) فەرمان دەدات، و هەموو تیمە پزیشکییەکان، پۆلیس، ئاگرکوژێنەوە و فەرمانگەکان لە ژێر ئەم فەرماندەییەدا کار دەکەن."},{heading:"١. سیستەمی فەرماندەیی ڕووداو (ICS)",body:"ستانداردێکی یەکگرتوو بۆ هەموو لایەنەکان:",points:["خولەکانی ICS-100 و ICS-200 بۆ کارمەندە سەرەکییەکان پێویستن.","فەرماندەی ڕووداو (IC): تەنها یەک کەس، و بەرپرسیارێتیی گشتیی ڕووداوەکە لە ئەستۆی ئەوە.","پێنج بەش: فەرماندەیی (Command)، کارەکان (Operations)، پلاندانان (Planning)، لۆجستیک (Logistics)، دارایی و کارگێڕی (Finance/Admin).","سنووری سەرپەرشتی (Span of Control): ٣-٧ کەس بۆ هەر سەرپەرشتیارێک (باشترین ٥).","هەر ڕووداوێک ناوێکی تایبەت وەردەگرێت (بەروار + شوێن + جۆر).","زمانی سادە (Plain Language): کۆد و کورتکراوەی تایبەت بەکار مەهێنە.","پلانی کاری ڕووداو (IAP) بۆ هەر ماوەیەکی کار (Operational Period)، کە بە گشتی ١٢ یان ٢٤ کاتژمێرە.","ئەگەر چەند لایەنێک بەرپرس بوون: فەرماندەیی یەکگرتوو (Unified Command) — فەرماندەکانی لایەنەکان پێکەوە یەک پلان دادەنێن."]},{heading:"٢. پەیوەندیکردن بە ١١٥ — چی بڵێیت",body:"ئارام بە، بە ڕوونی قسە بکە و ئەم شتانە بەم ڕیزبەندییە بڵێ:",points:["١. پێش هەموو شتێک شوێنی دروست: بینا و ناوی فەرمانگە، شەقام، نیشانەیەکی دیاری نزیک و نهۆم.","٢. چی ڕوویدا: ئاگر، تەقینەوە، ڕووداو، ژەهراویبوون.","٣. چەند کەس بریندار بوون یان گیریان خواردووە.","٤. هەر مەترسییەک: بڵاوبوونەوەی ئاگر، گاز، کارەبا، مادەی کیمیایی.","٥. ناوی خۆت و ژمارەی تەلەفۆنەکەت.","٦. وەڵامی پرسیارەکان بدەوە، ڕێنماییەکان جێبەجێ بکە و تەلەفۆنەکە دامەخە تا پێت نەڵێن."]},{heading:"٣. وەڵامدانەوەی چەند لایەنێک (Multi-Agency Response)",body:"کاتێک چەند لایەنێک دەگەن:",points:["١١٥ بەرگریی شارستانی: کوژاندنەوەی ئاگر، ڕزگارکردن، مادە مەترسیدارەکان (HazMat).","١٢٢ ئەمبولانس: چارەسەری پزیشکی و گواستنەوە.","١٠٤ پۆلیس: گەمارۆدانی دەوروبەر و ڕێکخستنی هاتوچۆ.","فەرمانگەی کارەبا: بڕینی کارەبا.","فەرمانگەکانی ئاو و گاز: بڕینی ئاو و گاز ئەگەر دزەکردن هەبوو.","وەزارەتی تەندروستی: ئامادەکردنی نەخۆشخانەکان.","دەستەی ژینگە: ڕژانی مادە کیمیاییەکان.","ناوەندی کارەکانی تەنگانە (EOC — Emergency Operations Center) بۆ ڕووداوە گەورەکان."]},{heading:"٤. ڕۆڵی فەرمانگە لە کاتی تەنگانەدا",body:"چی دەبێت بکەیت تا ١١٥ دەگات:",points:["١. پەیوەندی بە ١١٥ بکە (و ١٢٢ ئەگەر بریندار هەبوون) و پێش هەموو شتێک شوێنەکە بڵێ.","٢. ئاگادارکردنەوەی ناوخۆیی چالاک بکە (زەنگی ئاگر یان بڵندگۆ).","٣. کارمەندان لە خاڵی کۆبوونەوە — ژماردنی کەسەکان (Accountability).","٤. نەخشەی بیناکە ئامادە بکە: مەترسییەکان و سەمامەکانی کارەبا، گاز و ئاو.","٥. ئەفسەری پەیوەندی (Liaison Officer): تەنها یەک کەس پەیوەندی لەگەڵ ١١٥ دەکات.","٦. پەڕەکانی SDS و لیستەکانی پەیوەندی ئامادە بکە.","٧. ڕێکخستنی هاتوچۆ: ڕێگا بۆ ئۆتۆمبێلەکانی تەنگانە کراوە بهێڵەرەوە.","٨. بەرپرسی زانیاریی گشتی (PIO): زانیاریدان بە خەڵک و میدیا بە شێوەیەکی ڕێکخراو.","٩. تۆمارکردن: وێنە، ڤیدیۆ و قسەی شایەتحاڵەکان.","١٠. ڕادەستکردنی فەرماندەیی: کاتێک ١١٥ دەگات، فەرماندەیی ڕادەستی فەرماندەی ١١٥ دەکرێت."]},{heading:"٥. تیمی وەڵامدانەوەی تەنگانە لە فەرمانگەدا (ERT)",body:"پێکهاتەی پێشنیارکراو:",points:["فەرماندەی ڕووداو (IC): بەڕێوەبەر یان جێگری بەڕێوەبەر.","هەماهەنگکاری ئاگادارکردنەوە: دوگمەی ئاگر و پەیوەندی.","بەرپرسانی نهۆم (Floor Wardens): ٢ لە هەر نهۆمێکدا، بۆ ڕێگاکانی دەرچوون.","تیمی فریاکەوتنی سەرەتایی: ٢-٣ کارمەندی ڕاهێنراو لەسەر CPR و AED.","تیمی گەڕان: پشکنینی ژوورەکان و دڵنیابوونەوە لە چۆڵکردنی بیناکە.","تیمی ئاگرکوژێنەرەوەکان: کارمەندی ڕاهێنراو بۆ کوژاندنەوەی ئاگری بچووک لە قۆناغی سەرەتادا.","پەیوەندی: تەلەفۆن لەگەڵ ١١٥ و هەماهەنگیی ناوخۆیی.","ڕاهێنان: ڕاهێنانی سەرەتایی و نوێکردنەوەی ساڵانە."]},{heading:"٦. ڕاهێنان و تاقیکردنەوە (Drills + Tabletop Exercises)",body:"جۆرەکانی ڕاهێنان (FEMA HSEEP):",points:["ڕاهێنانی چۆڵکردن (Drill): بەپێی ئەم بەرنامەیە، هەر ٣ مانگ جارێک.","ڕاهێنانی سەر مێز (Tabletop Exercise): بەڕێوەبەران و بەرپرسان لە دەوری مێزێک سیناریۆیەک تاوتوێ دەکەن.","ڕاهێنانی کارەکی (Functional Exercise): تەنها تیمەکان و ئەرکە سەرەکییەکان (پەیوەندی، فەرماندەیی) تاقی دەکرێنەوە.","ڕاهێنانی تەواو (Full-Scale): هەموو بیناکە و لایەنە دەرەکییەکان، لانیکەم ساڵی یەک جار.","ڕاپۆرتی دوای ڕاهێنان (After-Action Report) بە زوویی بنووسە.","ئامانج: دیاریکردنی ئەوەی چی باش بوو، چی کەم بوو و چی دەبێت بگۆڕدرێت.","باشترکردنی بەردەوام: ئەنجامەکانی AAR بخە ناو ڕێکارەکانی کار (SOP)."]},{heading:"٧. پلانی پەیوەندی (Communication Plan)",body:"بەبێ پەیوەندی، هیچ کارێک بە ڕێکوپێکی ناڕوات:",points:["سەرەکی: تەلەفۆنەکانی فەرمانگە و سیستەمی بڵندگۆ (PA).","دووەم: مۆبایل و ڕادیۆی دوولایەنە.","سێیەم: ناردنی کەس بە پێ (Runners).","جێگرەوە: تەلەفۆنی مانگی دەستکرد بۆ ڕووداوە گەورەکان.","تاقیکردنەوە: هەموو هەفتەیەک بۆ تیمە سەرەکییەکان.","لیستی تەلەفۆنەکان: ٢٤/٧ ئامادە و نوێکراوە بێت.","بۆ خەڵک: هێڵی تەلەفۆن، ماڵپەڕ و تۆڕە کۆمەڵایەتییەکان — تەنها لە ڕێگەی PIO ەوە.","تێبینی: لە ڕووداوە گەورەکاندا تۆڕی مۆبایل لەوانەیە قەرەباڵغ ببێت — نامەی SMS بە گشتی باشتر دەگات."]},{heading:"٨. هەڵسەنگاندنی دوای ڕووداو (After-Action Review)",body:"پشکنینی دوای ڕووداو:",points:["پێشنیار: لە ماوەی ٧٢ کاتژمێردا دوای هەر ڕووداوێک، کاتێک بیرەوەرییەکان هێشتا تازەن.","بەشداریی هەموو لایەنەکان: IC، کارەکان، لۆجستیک و لایەنە دەرەکییەکان.","٤ پرسیار: چی پلانی بۆ دانرابوو؟ چی ڕوویدا؟ بۆچی جیاوازی هەبوو؟ جاری داهاتوو چی دەگۆڕین؟","پێوەرەکان: کاتی وەڵامدانەوە، ژمارەی برینداران، زیانە ماددییەکان.","تۆمارکردن: ڕاپۆرتی وانە وەرگیراوەکان (Lessons Learned).","نوێکردنەوە: SOP، پلانی تەنگانە (EOP) و کەرەستەکانی ڕاهێنان.","بەدواداچوون: دوای ٣٠، ٦٠ و ٩٠ ڕۆژ جێبەجێکردن بپشکنە.","هاوبەشکردن: ئەنجامەکان لەگەڵ لایەنەکانی تر هاوبەش بکە."]}],media:[{kind:"video",src:"media/videos/gov_ics_demo.mp4",title:"ICS لە کرداردا (ICS in Action)",description:"ICS لە کارەساتێکی ڕاستەقینەدا"},{kind:"image",src:"media/images/gov_salute_card.png",title:"کارتی پەیوەندیکردن بە ١١٥",description:"کارتی بیرخستنەوە: کاتێک پەیوەندی بە ١١٥ دەکەیت چی بڵێیت"}],quiz:[{question:"لە ICS دا، چەند فەرماندەی ڕووداو (IC) پێویستە؟",options:[{text:"٣-٥",correct:!1},{text:"تەنها یەک",correct:!0},{text:"هەر کارمەندێک",correct:!1},{text:"٢-٤",correct:!1}],explanation:"لە ICS دا یەک فەرماندەی ڕووداو هەیە. ئەگەر چەند لایەنێک بەرپرس بوون، فەرماندەیی یەکگرتوو (Unified Command) بە یەک پلانی هاوبەش کار دەکات."},{question:"کاتێک پەیوەندی بە ١١٥ دەکەیت، سەرەتا چی دەڵێیت؟",options:[{text:"ناوی خۆت و ڕۆڵەکەت",correct:!1},{text:"شوێنی دروست: بینا، شەقام، نیشانەیەکی دیاری نزیک و نهۆم",correct:!0},{text:"ڕووداوەکە کەی دەستی پێکرد",correct:!1},{text:"چ کەرەستەیەکت لایە",correct:!1}],explanation:"پێش هەموو شتێک شوێنی دروست بڵێ. پاشان بڵێ چی ڕوویدا، چەند کەس بریندار بوون یان گیریان خواردووە، هەر مەترسییەک، و ناو و ژمارەی تەلەفۆنەکەت."},{question:"کاتێک ١١٥ دەگات، فەرماندەیی دەکەوێتە دەستی کێ؟",options:[{text:"ERT بەردەوام دەبێت",correct:!1},{text:"فەرماندەی ١١٥",correct:!0},{text:"ئەفسەری پەیوەندی (Liaison)",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"ڕادەستکردنی فەرماندەیی: کاتێک ١١٥ دەگات، فەرماندەیی ڕادەستی فەرماندەی ١١٥ دەکرێت و ERT یارمەتیی دەدات."},{question:"ڕاهێنانی سەر مێز (Tabletop Exercise) چییە؟",options:[{text:"ڕاهێنانی چۆڵکردنی هەموو بیناکە",correct:!1},{text:"تاوتوێکردنی سیناریۆیەک لە دەوری مێزێک لەگەڵ بەرپرسان",correct:!0},{text:"تاقیکردنەوەی سیرین",correct:!1},{text:"ڕاهێنانی بەکارهێنانی ئاگرکوژێنەرەوەکان",correct:!1}],explanation:"ڕاهێنانی سەر مێز تاوتوێکردنی سیناریۆیەکە بەبێ جووڵاندنی کەس و کەرەستە، بۆ ئەوەی پلان و ئەرکەکان تاقی بکرێنەوە (FEMA HSEEP)."},{question:"پێشنیار دەکرێت هەڵسەنگاندنی دوای ڕووداو (AAR) لە ماوەی چەند کاتژمێردا ئەنجام بدرێت؟",options:[{text:"٢٤",correct:!1},{text:"٤٨",correct:!1},{text:"٧٢",correct:!0},{text:"١٦٨",correct:!1}],explanation:"لە ماوەی ٧٢ کاتژمێردا — کاتێک بیرەوەرییەکان هێشتا تازە و تەواون."},{question:"سنووری سەرپەرشتی (Span of Control) لە ICS دا چەندە؟",options:[{text:"٢ کەس",correct:!1},{text:"٣-٧ کەس",correct:!0},{text:"١٠+ کەس",correct:!1},{text:"بێ سنوور",correct:!1}],explanation:"بەپێی NIMS: ٣-٧ کەس بۆ هەر سەرپەرشتیارێک، و ٥ باشترینە."}]}],t={lessons:e};export{t as default,e as lessons};
